INSERT INTO package_questions (id, package_id, question_json, status, order_index) VALUES ('1d562f29-e755-4991-a50a-1a98ed590aad', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Paciente masculino, 42 anos, natural de Pernambuco e residente em São Paulo há 10 anos, trabalhador da construção civil, procura a Unidade Básica de Saúde com queixa de tosse produtiva com expectoração amarelada e ocasionalmente hemoptoica há cerca de 2 meses. Relata também febre vespertina não aferida, sudorese noturna que o obriga a trocar a roupa de cama e perda ponderal de 8 kg no período (peso habitual de 75 kg). É tabagista (20 maços-ano) e etilista social. Ao exame físico: emagrecido, eupneico (FR: 18 irpm), afebril no momento, FC: 88 bpm, PA: 110/70 mmHg. Ausculta pulmonar revela estertores creptantes em ápice direito e redução do murmúrio vesicular na mesma região. Sem outras alterações dignas de nota. O médico solicita radiografia de tórax, que demonstra infiltrado reticulonodular com área de cavitação de 2 cm no lobo superior direito. Com base no quadro clínico e radiológico apresentado, a conduta inicial mais adequada para a investigação diagnóstica é:", "options": {"a": "Solicitar teste rápido molecular para tuberculose (TRM-TB) e cultura para micobactérias em amostra de escarro.", "b": "Iniciar esquema RIPE (Rifampicina, Isoniazida, Pirazinamida e Etambutol) imediatamente devido à alta suspeição clínica.", "c": "Solicitar tomografia de tórax de alta resolução para melhor caracterização da lesão cavitária.", "d": "Realizar broncoscopia com lavado broncoalveolar para pesquisa de fungos e micobactérias.", "e": "Prescrever amoxicilina com clavulanato por 10 dias e reavaliar o paciente após o término do tratamento."}, "answer": "a", "rationale": "A apresentação clínica de tosse produtiva e hemoptise crônica, associada a sintomas constitucionais (febre vespertina, sudorese noturna e perda de peso) em um paciente com achados radiológicos sugestivos (infiltrado e cavitação em ápice pulmonar), torna a tuberculose pulmonar o principal diagnóstico diferencial. De acordo com o Manual de Recomendações para o Controle da Tuberculose no Brasil, em adultos e adolescentes com suspeita de TB pulmonar, a conduta diagnóstica inicial de escolha é a realização do Teste Rápido Molecular (TRM-TB), que detecta o DNA do Complexo M. tuberculosis e a resistência à rifampicina em poucas horas. A cultura para micobactérias também deve ser solicitada em conjunto para todos os casos suspeitos, pois é o padrão-ouro e permite a realização do teste de sensibilidade a outras drogas.", "option_rationales": {"a": "Correta. O TRM-TB é o método preferencial para o diagnóstico inicial devido à sua alta sensibilidade e rapidez, devendo ser complementado pela cultura.", "b": "Incorreta. O tratamento nunca deve ser iniciado sem a tentativa de confirmação bacteriológica, a menos que o estado clínico seja crítico, o que não é o caso.", "c": "Incorreta. Embora a TC ajude, a prioridade absoluta em um sintomático respiratório é a confirmação microbiológica da TB.", "d": "Incorreta. A broncoscopia é um exame invasivo reservado para casos onde o escarro é negativo ou o paciente não consegue expectorar.", "e": "Incorreta. Tratar como pneumonia bacteriana comum retardaria o diagnóstico de uma doença infectocontagiosa grave com alta suspeição clínica."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Tuberculose Pulmonar", "Diagnóstico", "TRM-TB", "Saúde Pública"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 0), ('cd8707da-5a25-426e-bae7-a23b948ec67d', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Uma paciente de 34 anos, técnica de enfermagem em um hospital universitário, apresenta-se com história de tosse seca há 3 semanas, associada a dor pleurítica à direita e febre baixa intermitente (37,8°C). Nega perda de peso importante ou sudorese noturna. Relata contato recente (há 6 meses) com paciente bacilífero em sua unidade de trabalho, sem uso adequado de equipamento de proteção individual na ocasião. Ao exame físico, apresenta diminuição global do murmúrio vesicular em base direita, com macicez à percussão na mesma região. Radiografia de tórax revela derrame pleural à direita ocupando cerca de um terço do hemitórax. Foi realizada toracentese diagnóstica que demonstrou líquido pleural exsudativo, com predomínio de linfócitos (85%), glicose de 70 mg/dL e níveis de Adenosina Deaminase (ADA) de 62 U/L. A pesquisa de BAAR e o TRM-TB no líquido pleural foram negativos. Qual o diagnóstico mais provável para esta paciente e a conduta recomendada?", "options": {"a": "Tuberculose pleural; iniciar tratamento com esquema RIPE com base no quadro clínico-laboratorial.", "b": "Derrame pleural paraneumônico; iniciar antibioticoterapia de amplo espectro.", "c": "Neoplasia pleural (Mesotelioma); realizar biópsia pleural por agulha ou pleuroscopia.", "d": "Lúpus Eritematoso Sistêmico; pesquisar anticorpos antinucleares (FAN) e células LE no líquido.", "e": "Empiema pleural tuberculoso; realizar drenagem torácica imediata em selo d''água."}, "answer": "a", "rationale": "A tuberculose pleural é a forma mais comum de tuberculose extrapulmonar em indivíduos jovens e imunocompetentes. No diagnóstico, o derrame pleural é caracteristicamente um exsudato linfocítico. O nível de ADA (Adenosina Deaminase) elevado (geralmente > 40 U/L) possui alto valor preditivo positivo em regiões com alta prevalência de TB. Embora a sensibilidade da baciloscopia e do TRM-TB no líquido pleural seja baixa (< 10%), o conjunto de quadro clínico (febre, dor pleurítica, contato prévio), líquido exsudativo linfocítico e ADA elevado autorizam o diagnóstico e o início do tratamento, mesmo sem a confirmação de biópsia em primeira instância no contexto brasileiro.", "option_rationales": {"a": "Correta. A tríade clínico-epidemiológica e o nível elevado de ADA no exsudato linfocítico são clássicos da TB pleural.", "b": "Incorreta. O quadro é insidioso e o líquido não possui características de exsudato neutrofílico típico de pneumonia.", "c": "Incorreta. Embora possível, o ADA elevado e a história epidemiológica tornam a TB muito mais provável em uma paciente jovem.", "d": "Incorreta. O derrame lúpico costuma apresentar ADA mais baixo e outros sintomas sistêmicos ausentes aqui.", "e": "Incorreta. O derrame da TB pleural clássica é reacional e não um empiema (que conteria pus e alta carga bacteriana), não exigindo drenagem de rotina."}, "difficulty": "dificil", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Tuberculose Pleural", "ADA", "Líquido Pleural", "Diagnóstico"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 1), ('13b8d022-42aa-4eeb-96e7-f348a8886dda', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Homem de 28 anos, portador de HIV (último CD4: 120 células/mm³, carga viral indetectável), em uso regular de TARV há 2 anos, apresenta quadro de cefaleia holocraniana progressiva, vômitos em jato e febre há 10 dias. Há 2 dias, a família relata confusão mental e somolência. Ao exame físico: Glasgow 12, rigidez de nuca presente, sinal de Brudzinski positivo. Sem déficits motores focais. Fundo de olho demonstra borramento de papila bilateral. Realizada tomografia de crânio que demonstrou discreto realce meníngeo basal, sem lesões expansivas ou efeito de massa. A análise do líquido cefalorraquidiano (LCR) revela: 250 células/mm³ (80% linfócitos), proteínas de 180 mg/dL, glicose de 22 mg/dL (glicemia plasmática: 98 mg/dL) e coloração de tinta da China negativa. O TRM-TB no líquor detectou M. tuberculosis sem resistência à rifampicina. Além do início imediato do esquema RIPE, qual medida terapêutica adicional é fundamental para reduzir a mortalidade e as sequelas neurológicas deste paciente?", "options": {"a": "Adição de dexametasona ao esquema terapêutico por 4 a 8 semanas.", "b": "Mudança da Pirazinamida por Levofloxacino devido à melhor penetração no SNC.", "c": "Drenagem liquórica externa imediata para controle da hipertensão intracraniana.", "d": "Suspensão temporária da TARV para evitar a síndrome inflamatória de reconstituição imune (IRIS).", "e": "Adição de Anfotericina B lipossomal até o resultado da cultura para fungos."}, "answer": "a", "rationale": "A meningoencefalite tuberculosa é a forma mais grave de TB, especialmente em pacientes com imunossupressão avançada. O uso de corticosteroides (dexametasona ou prednisolona) como terapia adjuvante é mandatório e comprovadamente reduz a mortalidade e melhora o prognóstico neurológico, ao modular a resposta inflamatória no espaço subaracnoideo e diminuir o edema cerebral. O início deve ser concomitante ao RIPE.", "option_rationales": {"a": "Correta. O corticosteroide é a única terapia adjuvante com evidência sólida de redução de mortalidade na TB meníngea.", "b": "Incorreta. A Pirazinamida penetra bem no LCR e faz parte do esquema padrão de 1ª linha; o Levofloxacino é droga de 2ª linha.", "c": "Incorreta. A drenagem é reservada para casos de hidrocefalia obstrutiva evidente, não sendo a ''medida fundamental'' geral de primeira linha descrita.", "d": "Incorreta. Em pacientes já em TARV, ela deve ser mantida. Se não estivessem, a introdução seria postergada por 8 semanas, mas nunca suspensa.", "e": "Incorreta. O TRM-TB já confirmou a causa; o líquor linfocítico com glicose baixa e proteína alta é típico de TB, não justificando Anfotericina após confirmação de TB."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Tuberculose Clínica", "HIV/AIDS", "Neurologia", "Corticoterapia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 2), ('2ae65b32-2f95-45d6-a5b9-5cf576cbf583', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um paciente de 55 anos, diabético e ex-tabagista, está em tratamento para tuberculose pulmonar sensível há 45 dias com o esquema RIPE (Rifampicina, Isoniazida, Pirazinamida e Etambutol). Durante consulta de acompanhamento, refere que há uma semana vem notando ''visão embaçada'' e dificuldade para distinguir cores, especialmente o vermelho e o verde. Nega cefaleia ou dor à movimentação ocular. Ao exame oftalmológico, observa-se redução da acuidade visual bilateral e discromatopsia. O fundo de olho é normal nesta fase inicial. Qual fármaco do esquema terapêutico é o provável responsável por este efeito adverso e qual a conduta imediata recomendada?", "options": {"a": "Etambutol; suspender o fármaco e encaminhar para avaliação especializada.", "b": "Isoniazida; administrar Piridoxina (Vitamina B6) em altas doses.", "c": "Rifampicina; orientar que a alteração é transitória e não exige suspensão.", "d": "Pirazinamida; dosar níveis de ácido úrico no sangue.", "e": "Estreptomicina; realizar audiometria prioritária."}, "answer": "a", "rationale": "O Etambutol pode causar neurite óptica retrobulbar, que se manifesta clinicamente como redução da acuidade visual, alterações no campo visual (escotomas centrais) e perda da percepção de cores (verde-vermelho). É um efeito adverso dose-dependente e, por ser frequentemente reversível se detectado precocemente, a suspensão imediata da droga é a medida mais importante. Pacientes acima de 55 anos ou com disfunção renal têm maior risco.", "option_rationales": {"a": "Correta. A toxicidade ocular (neurite óptica) é o efeito colateral clássico do Etambutol.", "b": "Incorreta. A Isoniazida causa neuropatia periférica (dormência), não distúrbios de visão colorida.", "c": "Incorreta. A Rifampicina pode deixar lágrimas/urina laranjas, mas não causa perda de visão ou discromatopsia.", "d": "Incorreta. A Pirazinamida causa hiperuricemia e hepatotoxicidade, sem relação com a visão.", "e": "Incorreta. A Estreptomicina é ototóxica (audição/equilíbrio) e não faz parte do esquema RIPE padrão inicial (é usada em casos especiais)."}, "difficulty": "facil", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Farmacologia", "Efeitos Adversos", "Etambutol", "Oftalmologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 3), ('aa138e0a-6ff4-4e14-8174-600c606fb934', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Paciente feminina, 29 anos, grávida (2ª gestação, 14 semanas), sem comorbidades conhecidas, apresenta tosse produtiva e febre baixa há 4 semanas. A investigação microbiológica por TRM-TB em escarro confirmou M. tuberculosis sensível à rifampicina. Sobre o tratamento da tuberculose ativa durante a gestação no Brasil, assinale a orientação correta:", "options": {"a": "O esquema RIPE deve ser iniciado normalmente, pois a Rifampicina, Isoniazida e Etambutol são seguros, e a Pirazinamida é recomendada pelo Ministério da Saúde brasileiro na gestação.", "b": "O tratamento deve ser adiado para o segundo trimestre para evitar teratogenicidade dos fármacos.", "c": "A Pirazinamida deve ser excluída do esquema, mantendo-se apenas Rifampicina, Isoniazida e Etambutol por 9 meses.", "d": "A Isoniazida deve ser evitada devido ao risco de malformações no tubo neural do feto.", "e": "Além do esquema RIPE, a estreptomicina deve ser adicionada para garantir a cura da gestante e prevenir a TB congênita."}, "answer": "a", "rationale": "No Brasil, o Ministério da Saúde recomenda o tratamento padrão com o esquema RIPE (Rifampicina, Isoniazida, Pirazinamida e Etambutol) para gestantes com tuberculose. Estudos e a vasta experiência clínica nacional demonstram segurança e eficácia, não havendo evidências de teratogenicidade significativa com essas drogas nas doses habituais. A Piridoxina (B6) é recomendada adicionalmente para prevenir neuropatia por Isoniazida na gestante.", "option_rationales": {"a": "Correta. O Brasil utiliza o esquema RIPE padrão em gestantes, tratando-as da mesma forma que não gestantes.", "b": "Incorreta. A TB não tratada é muito mais perigosa para a mãe e para o feto do que os fármacos.", "c": "Incorreta. Esta era uma recomendação antiga ou utilizada em outros países; no Brasil, a Pirazinamida é mantida.", "d": "Incorreta. A Isoniazida é segura na gestação; as malformações de tubo neural dependem de ácido fólico, não de Isoniazida.", "e": "Incorreta. A estreptomicina é estritamente contraindicada na gestação devido à toxicidade para o VIII par craniano fetal (surdez)."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Gestação", "Terapêutica", "Saúde da Mulher", "Infectologia Clínica"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 4), ('99479f53-23da-4631-a85d-1850ad1efbc6', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Homem de 50 anos, alcoólatra crônico, em tratamento para tuberculose pulmonar há 20 dias, é levado à emergência por familiares com quadro de desorientação, náuseas intensas e icterícia evidente. Os exames laboratoriais revelam: AST (TGO) 520 U/L (VR: até 40), ALT (TGP) 480 U/L (VR: até 40), Bilirrubina Total 6,8 mg/dL (com direta de 5,1 mg/dL) e INR de 1,4. Ao ser diagnosticada a hepatotoxicidade grave induzida por fármacos antituberculose, qual a conduta imediata mais adequada quanto ao tratamento da TB?", "options": {"a": "Suspender imediatamente todos os fármacos do esquema RIPE.", "b": "Suspender apenas a Pirazinamida e a Isoniazida, mantendo Rifampicina e Etambutol.", "c": "Manter o tratamento e prescrever silimarina e complexo B para proteção hepática.", "d": "Suspender a Rifampicina e a Pirazinamida, mantendo Isoniazida e Etambutol por ser um esquema menos hepatotóxico.", "e": "Reduzir a dose de todos os fármacos para 50% até a normalização das enzimas."}, "answer": "a", "rationale": "A conduta na hepatotoxicidade induzida pelo tratamento da TB (definida como elevação de transaminases > 3x o valor de referência se sintomático, ou > 5x se assintomático, ou icterícia) é a suspensão imediata de todos os fármacos potencialmente hepatotóxicos (Rifampicina, Isoniazida e Pirazinamida). Após a normalização dos exames laboratoriais e melhora clínica, os fármacos devem ser reintroduzidos sequencialmente para identificar o causador.", "option_rationales": {"a": "Correta. A suspensão total é a regra de ouro para evitar falência hepática fulminante em caso de toxicidade medicamentosa evidente (icterícia e elevação > 10x das enzimas).", "b": "Incorreta. A Rifampicina também é hepatotóxica e deve ser suspensa na fase aguda.", "c": "Incorreta. O uso de ''protetores hepáticos'' não substitui a necessidade vital de interromper a agressão tóxica.", "d": "Incorreta. A Isoniazida é um dos principais causadores de lesão hepática grave.", "e": "Incorreta. A redução de dose não resolve a toxicidade idiossincrática ou metabólica e pode induzir resistência bacteriana."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Hepatotoxicidade", "Segurança do Paciente", "Efeitos Adversos", "Infectologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 5), ('038c2cae-77c7-4bfe-b254-1adf57bdf557', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um homem de 38 anos, em situação de rua, foi diagnosticado com tuberculose pulmonar há 4 meses. Ele iniciou o esquema RIPE, mas abandonou o tratamento após 30 dias por sentir-se melhor. Retorna agora com tosse produtiva intensa, febre alta e emagrecimento importante. O TRM-TB realizado no retorno demonstrou presença de M. tuberculosis com detecção de resistência à rifampicina. Este quadro caracteriza-se como um provável caso de:", "options": {"a": "Tuberculose Multirresistente (TB-MDR) ou Resistente à Rifampicina (TB-RR).", "b": "Tuberculose Sensível com recidiva precoce por falha imunológica.", "c": "Tuberculose Extensivamente Resistente (TB-XDR).", "d": "Tuberculose Monorresistente apenas à Isoniazida.", "e": "Pneumonia de hipersensibilidade por exposição tardia a micobactérias."}, "answer": "a", "rationale": "A resistência à rifampicina (TB-RR), detectada isoladamente ou em associação à resistência a outra droga (como a isoniazida, configurando TB-MDR), exige a mudança imediata para esquemas especiais (geralmente contendo bedaquilina, linezolida e fluoroquinolonas). O abandono e o tratamento irregular são os principais fatores de risco para a seleção de cepas resistentes.", "option_rationales": {"a": "Correta. O TRM-TB identifica especificamente a resistência à rifampicina, definindo o caso como TB-RR, manejado como MDR no Brasil.", "b": "Incorreta. A detecção de resistência genotípica pelo TRM invalida o diagnóstico de TB sensível.", "c": "Incorreta. A TB-XDR exige resistência à rifampicina, isoniazida, uma fluoroquinolona e mais uma droga do Grupo A.", "d": "Incorreta. O teste especificamente apontou resistência à rifampicina.", "e": "Incorreta. Trata-se de uma doença infecciosa confirmada, não um quadro imunológico/alérgico."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Resistência Bacteriana", "TB-MDR", "Epidemiologia", "Saúde Pública"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 6), ('f1081c96-2aa9-4b2e-865a-3f556e923c1c', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Durante uma investigação de contatos de um paciente com Tuberculose Pulmonar bacilífera (baciloscopia ++), o filho do paciente, de 7 anos, é avaliado. Ele está assintomático, tem radiografia de tórax normal e exame físico sem alterações. Realizou-se a Prova Tuberculínica (PPD), que resultou em 12 mm. O cartão vacinal mostra cicatriz de BCG ao nascimento. Qual a interpretação e a conduta preconizada pelo Ministério da Saúde para esta criança?", "options": {"a": "Infecção Latente por Tuberculose (ILTB); iniciar tratamento preventivo com Isoniazida ou Rifampicina.", "b": "Tuberculose Ativa com apresentação paucibacilar; iniciar esquema RIPE infantil.", "c": "Imunização prévia por BCG apenas; não requer conduta adicional além da vigilância clínica.", "d": "Tuberculose Larvada; solicitar tomografia de tórax para identificar linfonodomegalias hilares.", "e": "Falso-positivo por exposição a micobactérias não tuberculosas; repetir o PPD em 3 meses."}, "answer": "a", "rationale": "Em crianças contatos de bacilíferos, um PPD ≥ 5 mm (independente do status da vacina BCG anterior, se aplicada há mais de 2 anos) com exame clínico e radiológico normal define o diagnóstico de Infecção Latente por Tuberculose (ILTB). A conduta correta é o tratamento preventivo da tuberculose (TPTB) para evitar a progressão para doença ativa, sendo a Rifampicina por 4 meses ou a Isoniazida por 6 a 9 meses as opções terapêuticas preferenciais.", "option_rationales": {"a": "Correta. Contato próximo, assintomático, RX normal e PPD reagente é o cenário clássico para tratamento de ILTB.", "b": "Incorreta. Para diagnosticar doença ativa seria necessário sintoma ou alteração radiológica.", "c": "Incorreta. O valor de 12 mm em contato de bacilífero é valorizado como infecção, não apenas resposta vacinal.", "d": "Incorreta. O termo clínico correto é ILTB e a conduta é profilaxia, não exames invasivos em criança assintomática com RX normal.", "e": "Incorreta. No Brasil, país de alta carga, o PPD reagente em contatos deve ser sempre atribuído à infecção pelo M. tuberculosis."}, "difficulty": "dificil", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["ILTB", "Pediatria", "Controle de Contatos", "PPD"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 7), ('f4777887-bc46-47bd-88c5-87921248bf3d', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Paciente de 19 anos, do sexo masculino, procura atendimento por aumento de volume indolor em região cervical lateral direita há 3 semanas. Relata que o nódulo é de consistência endurecida, pouco móvel e não apresenta sinais inflamatórios (dor, calor ou rubor). Nega febre, mas refere perda de peso não intencional de 3 kg e astenia. Não há história de contato conhecido com tuberculose. Realizou ultrassonografia cervical que revelou conglomerado de linfonodos com áreas centrais hipoecoicas sugestivas de necrose. A biópsia excisional do linfonodo demonstrou inflamação granulomatosa crônica com necrose de caseificação. A baciloscopia do material foi negativa. Qual o provável diagnóstico e o principal sítio de acometimento da tuberculose extrapulmonar neste caso?", "options": {"a": "Tuberculose Ganglionar; é a forma extrapulmonar mais comum em imunocompetentes e HIV negativos no Brasil.", "b": "Linfoma de Hodgkin; a necrose de caseificação é um achado patognomônico de doenças linfoproliferativas.", "c": "Sarcoidose; a presença de necrose caseosa afasta o diagnóstico de Tuberculose.", "d": "Artrite Reumatóide com nódulo necrobiótico cervical.", "e": "Câncer de Tireoide metastático; o granuloma é uma reação do hospedeiro ao tumor."}, "answer": "a", "rationale": "A tuberculose ganglionar cervical (também conhecida historicamente como escrófula) é a forma mais frequente de tuberculose extrapulmonar em crianças e adultos jovens imunocompetentes. A patologia característica é o granuloma com necrose de caseificação (caseosa). A baciloscopia do material biopsiado costuma ser negativa devido à natureza paucibacilar da lenha, mas o achado histopatológico em contexto clínico sugestivo é altamente diagnóstico no Brasil.", "option_rationales": {"a": "Correta. A descrição clínica e o granuloma caseoso em linfonodo definem a TB ganglionar.", "b": "Incorreta. O linfoma não apresenta necrose caseosa (que é típica de micobactérias ou fungos).", "c": "Incorreta. Na sarcoidose, os granulomas são tipicamente ''não caseificantes''.", "d": "Incorreta. Nódulos reumatoides têm histologia diferente e acometem outras regiões.", "e": "Incorreta. O granuloma caseoso não é uma característica de metástase de tumor de tireoide."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Tuberculose Extrapulmonar", "Patologia", "Linfadenopatia", "Escrófula"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 8), ('a57bd1f2-6c7c-4294-8083-9e466a7797f1', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um presidiário de 45 anos apresenta tosse crônica e cansaço. Ele realiza o Teste Rápido Molecular (TRM-TB), que indica: ''M. tuberculosis detectado: ALTO'' e ''Resistência à Rifampicina: NÃO DETECTADA''. O médico assistente solicita também uma cultura para micobactérias com teste de sensibilidade (TS). Por que a cultura é necessária se o teste molecular já descartou resistência à rifampicina e confirmou o diagnóstico?", "options": {"a": "Para detectar resistência a outros fármacos (como a Isoniazida), realizar vigilância de cepas circulantes e testar sensibilidade em caso de falha terapêutica.", "b": "Porque o TRM-TB possui baixa sensibilidade para confirmar a cura após o tratamento.", "c": "Para diferenciar o M. tuberculosis das micobactérias atípicas (não tuberculosas).", "d": "Para verificar se o paciente é portador de fungos associados em ''cavidade'' pulmonar de TB prévia.", "e": "A cultura não é mais necessária segundo os protocolos atuais se o TRM-TB for positivo em ''ALTO'' nível."}, "answer": "a", "rationale": "Embora o TRM-TB seja excelente para o diagnóstico rápido e detecção de resistência à rifampicina, ele não detecta resistência a outras drogas essenciais, como a Isoniazida (configurando monorresistência ou resistência MDR se associada). A cultura continua sendo o padrão-ouro e é fundamental para a vigilância epidemiológica, controle de cura e ajuste de esquemas em casos complexos ou recidivas.", "option_rationales": {"a": "Correta. A cultura complementa o molecular permitindo o teste de sensibilidade (TS) completo para todas as drogas do esquema.", "b": "Incorreta. O TRM-TB detecta DNA de bactérias mortas, logo não serve para controle de cura, mas isso não justifica o pedido no diagnóstico inicial.", "c": "Incorreta. O TRM-TB é específico para o complexo M. tuberculosis.", "d": "Incorreta. Cultura de micobactérias é em meio específico (Löwenstein-Jensen), não serve para fungos.", "e": "Incorreta. O protocolo brasileiro recomenda cultura e TS para todos os casos confirmados no diagnóstico."}, "difficulty": "dificil", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Microbiologia", "Diagnóstico", "Epidemiologia", "Saúde Pública"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 9), ('d063653e-5709-45e9-b0cd-367ded60de27', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Uma enfermeira de 26 anos participa da busca ativa de sintomáticos respiratórios em uma comunidade. Ela questiona qual o critério para considerar um indivíduo como ''sintomático respiratório'' na população geral para fins de investigação de tuberculose pulmonar. De acordo com as normas técnicas brasileiras, deve-se investigar a TB em:", "options": {"a": "Toda pessoa com tosse por tempo igual ou superior a 3 semanas.", "b": "Qualquer pessoa com febre vespertina, independente da presença de tosse.", "c": "Apenas indivíduos em situação de rua com tosse há mais de 10 dias.", "d": "Pessoas vivendo com HIV com qualquer tempo de tosse, mas moradores de área urbana apenas se tossirem há mais de 4 semanas.", "e": "Indivíduos que apresentem expectoração purulenta, independente do tempo de tosse."}, "answer": "a", "rationale": "Para a população geral no Brasil, o conceito de sintomático respiratório é definido pela presença de tosse por 3 semanas ou mais. No entanto, para populações em maior risco (situação de rua, privados de liberdade, indígenas e imunossuprimidos), esse período de corte é reduzido para qualquer tempo de tosse ou conforme a avaliação clínica inicial.", "option_rationales": {"a": "Correta. Este é o critério epidemiológico clássico adotado pelo Ministério da Saúde para triagem na população geral.", "b": "Incorreta. A febre é sintoma, mas a ''tosse'' é o marco definidor do sintomático respiratório na triagem de massa.", "c": "Incorreta. Para pessoas em situação de rua, qualquer tempo de tosse já justifica a investigação.", "d": "Incorreta. PVHIV também devem ser investigados com qualquer tempo de tosse.", "e": "Incorreta. A característica da secreção (purulenta ou hialina) não altera o critério cronológico da triagem."}, "difficulty": "facil", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Epidemiologia", "Saúde Coletiva", "Atenção Básica", "Protocolo"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 10), ('a73a78d5-fbda-461e-a4f5-7fbdba487a6a', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Paciente de 62 anos, com insuficiência renal crônica em hemodiálise e histórico de transplante renal prévio (em uso de tacrolimus e micofenolato), apresenta-se com febre de origem indeterminada, sudorese e perda de peso. Radiografia de tórax mostra padrão micronodular ''em grão de milheto'' distribuído difusamente em ambos os pulmões. Foi realizada biópsia de medula óssea que revelou granulomas caseosos. O diagnóstico é Tuberculose Miliar. Qual a fisiopatologia principal desta forma clínica e qual o risco iminente que deve ser investigado neste paciente?", "options": {"a": "Disseminação hematogênica do bacilo atingindo múltiplos órgãos; deve-se realizar punção lombar mandatória para excluir TB meníngea associada.", "b": "Aspiração maciça de bacilos das vias aéreas superiores; risco de insuficiência respiratória aguda hipoxêmica.", "c": "Reativação de foco de Simon em ápice pleural; risco de pneumotórax hipertensivo.", "d": "Fístula broncoesofágica por linfonodo roto; risco de mediastinite necrotizante.", "e": "Contaminação por micobactérias do banho de diálise; risco de sepse bacteriana secundária."}, "answer": "a", "rationale": "A tuberculose militar resulta da disseminação hematogênica (via sangue) do M. tuberculosis, levando à formação de pequenos granulomas em múltiplos órgãos (pulmões, fígado, baço, medula óssea, cérebro). É comum em pacientes com imunossupressão grave. Devido à alta frequência de acometimento concomitante do sistema nervoso central (até 30% dos casos de TB militar), a investigação do LCR é obrigatória mesmo na ausência de sintomas meníngeos clássicos.", "option_rationales": {"a": "Correta. A disseminação é hematogênica e a associação com meningite exige punção lombar preventiva no manejo hospitalar.", "b": "Incorreta. A via não é aspiração, e o padrão radiológico é sistêmico, não loco-regional pulmonar agudo comum.", "c": "Incorreta. Os focos de Simon são apicais e causam TB pulmonar cavitária clássica, não militar.", "d": "Incorreta. Esta é uma complicação anatômica rara, não relacionada à patogênese da TB militar.", "e": "Incorreta. A micobactéria da TB não se espalha pelo banho de diálise (seria via inalatória prévia em imunossuprimido)."}, "difficulty": "dificil", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Tuberculose Miliar", "Imunossuprimido", "Meningoencefalite", "Diagnóstico"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 11), ('815314e1-b524-4ef5-9c27-bf6c20479ef2', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um paciente em tratamento de tuberculose pulmonar há 3 meses apresenta persistência de baciloscopia (BAAR) de escarro positiva (++). Ele refere estar tomando os medicamentos corretamente. Esse cenário define um quadro de ''falha terapêutica''. Segundo o Ministério da Saúde, além da falha clínica ou microbiológica no 4º mês, quais as duas principais causas de falha que devem ser descartadas?", "options": {"a": "Resistência primária/adquirida aos fármacos e má adesão ao tratamento (não supervisionado).", "b": "Interação medicamentosa com anti-hipertensivos e tabagismo ativo.", "c": "Subtipo de micobactéria bovis (TB bovina) e uso de corticosteroides associados.", "d": "Idade avançada do paciente e co-infecção por vírus da Hepatite C.", "e": "Deficiência de vitamina D e baixa ingestão proteica."}, "answer": "a", "rationale": "A falha terapêutica na TB é caracterizada pela persistência de positividade no escarro no final do 4º mês de tratamento. As causas fundamentais a serem investigadas são a resistência bacteriana (que deve ser confirmada por teste de sensibilidade) e a falta de adesão ao tratamento, que é a causa mais comum de insucesso no Brasil. Por isso, o Tratamento Diretamente Observado (TDO) é preconizado para garantir a eficácia.", "option_rationales": {"a": "Correta. São os pilares do insucesso terapêutico: ou o remédio não funciona contra a cepa, ou o paciente não o toma.", "b": "Incorreta. Interações com anti-hipertensivos são raras e não causam ''falha'' por si sós.", "c": "Incorreta. M. bovis é sensível ao esquema, exceto à pirazinamida, mas não é causa comum de falha em massa.", "d": "Incorreta. Embora compliquem, não justificam a baciloscopia positiva persistente se o tratamento for adequado.", "e": "Incorreta. São fatores de risco para adoecer, mas não para falha se as drogas forem tomadas contra bacilo sensível."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Manejo Clínico", "Resistência", "ADESÃO", "TDO"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 12), ('0a007105-e40a-41f2-9fd7-b4bc50c58602', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um jovem de 21 anos, sem sintomas, vai realizar exame admissional para uma empresa e o PPD solicitado resulta em 15 mm. Ele é vacinado com BCG em dose única ao nascer e não tem histórico de contato com tuberculose. RX de tórax normal. Ele está preocupado com o resultado. Qual a melhor explicação e conduta?", "options": {"a": "Ele possui Infecção Latente e deve ser apenas acompanhado periodicamente com RX, sem necessidade de tratamento preventivo por não ser grupo de risco.", "b": "Possui Tuberculose latente confirmada e deve iniciar Rifampicina imediata.", "c": "É um falso-positivo devido à BCG, deve-se ignorar o resultado e liberar para o trabalho.", "d": "Ele deve realizar o teste IGRA (Interferon-Gamma Release Assay) para descartar reação cruzada com a BCG.", "e": "O PPD reagente indica que ele está protegido contra formas graves de Tuberculose por toda a vida."}, "answer": "a", "rationale": "Em indivíduos imunocompetentes sem contatos conhecidos e sem comorbidades de risco, um PPD reagente (mesmo > 10 mm) isolado num exame de rotina indica apenas que houve contato prévio com o bacilo (infecção). Nestes casos, o risco de progressão para doença ativa é baixo e não há indicação formal de tratamento preventivo de ILTB segundo o protocolo do Ministério da Saúde brasileiro, priorizando-se o tratamento para contatos próximos e grupos de risco definidos.", "option_rationales": {"a": "Correta. Não há benefício comprovado em tratar ILTB em indivíduos saudáveis sem história de contato recente/risco elevado.", "b": "Incorreta. Nem toda ILTB exige tratamento medicamentoso; depende da estratificação de risco.", "c": "Incorreta. Aos 21 anos, o efeito da BCG no PPD é desprezível; o resultado provavelmente indica infecção real, mas de baixo risco.", "d": "Incorreta. O IGRA ajudaria se houvesse dúvida clínica real, mas para fins admissionais o manejo é expectante.", "e": "Incorreta. O PPD reagente não é sinal de imunidade protetora, mas de memória imunológica à infecção."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["PPD", "ILTB", "Saúde Ocupacional", "Epidemiologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 13), ('70314c79-c4f8-4512-9fbb-be49d1e0f035', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Paciente masculino, 35 anos, inicia tratamento para TB pulmonar cavitária. O médico prescreve o esquema RIPE em dose fixa combinada (4 comprimidos em 1). Sobre a Rifampicina, fármaco central do esquema, qual das seguintes orientações sobre interações medicamentosas é a mais relevante?", "options": {"a": "Ela é um potente indutor das enzimas do citocromo P450, podendo reduzir drasticamente os níveis séricos de anticoncepcionais, warfarina e antirretrovirais (como Dolutegravir).", "b": "Ela inibe a excreção renal de lítio, podendo causar intoxicação grave.", "c": "Deve ser evitada com alimentos gordurosos pois sua absorção é inibida por eles.", "d": "Causa quelagem de ferro, devendo ser tomada distante de sulfato ferroso.", "e": "Aumenta o efeito da insulina, predispondo o paciente diabético a crises de hipoglicemia."}, "answer": "a", "rationale": "A Rifampicina é um dos indutores enzimáticos mais potentes conhecidos na farmacologia clínica. Ao induzir o citocromo P450 (CYP3A4), ela acelera o metabolismo de inúmeros fármacos, exigindo ajustes de dose frequentes (como dobrar a dose de dolutegravir para 50mg 12/12h ou mudar métodos contraceptivos hormonais para barreira ou DIU).", "option_rationales": {"a": "Correta. Esta interação é crítica no manejo de pacientes com comorbidades e HIV.", "b": "Incorreta. Não há interação relevante descrita com o lítio neste mecanismo.", "c": "Incorreta. Ela deve ser tomada preferencialmente em jejum, mas a interação com gordura não é o ponto central da farmacodinâmica relevante perguntada.", "d": "Incorreta. Esta é uma característica das tetraciclinas e quinolonas.", "e": "Incorreta. Frequentemente ocorre o oposto; o controle glicêmico pode ser dificultado pela alteração metabólica hepática."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Farmacologia", "Interação Medicamentosa", "Rifampicina", "HIV"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 14), ('eb724aec-b86d-4d49-a050-65963e5db294', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Paciente de 48 anos, soropositivo para o HIV há 5 anos, em uso irregular de Terapia Antirretroviral (TARV), procura o serviço de urgência com história de febre intermitente, tosse seca e cansaço aos esforços habituais há 3 semanas. Relata também aumento progressivo de volume em região axilar esquerda. Ao exame físico: descorado (2+/4+), febril (38,2°C), presença de linfonodomegalia axilar de 3 cm, indolor e aderida a planos profundos. Ausculta pulmonar com estertores esparsos. Radiografia de tórax evidencia infiltrado intersticial difuso e linfonodomegalia hilar bilateral. Realizada biópsia de linfonodo axilar cujo exame histopatológico revelou granulomas mal formados, com raros linfócitos e abundantes bacilos álcool-ácido resistentes (BAAR) na coloração de Ziehl-Neelsen. Sobre a apresentação da tuberculose em pacientes com imunodepressão grave (CD4 < 200 células/mm³), como no caso descrito, é correto afirmar:", "options": {"a": "A apresentação costuma ser atípica, com maior frequência de formas extrapulmonares, disseminadas e exames histopatológicos com granulomas paucibacilares e bem definidos.", "b": "A radiografia de tórax frequentemente apresenta cavitações apicais típicas, semelhantes às encontradas em pacientes imunocompetentes.", "c": "O quadro clínico tende a ser mais grave, com maior probabilidade de anergia aos testes cutâneos (PPD negativo) e achados radiológicos atípicos, como infiltrados em bases pulmonares e linfonodomegalias hilares.", "d": "O tratamento para este paciente deve ser iniciado apenas com Rifampicina e Etambutol para evitar a síndrome inflamatória de reconstituição imune (IRIS).", "e": "A presença de abundantes BAAR no linfonodo é um achado inesperado e sugere erro laboratorial, dado o caráter paucibacilar da TB ganglionar."}, "answer": "c", "rationale": "Em pacientes com infecção avançada pelo HIV e contagem baixa de linfócitos T-CD4, a imunidade celular está severamente comprometida. Isso altera a apresentação da tuberculose: 1) A formação de granulomas é deficiente (granulomas ''frouxos'' ou mal formados); 2) Há maior carga bacilar nas lesões (multibacilaridade paradoxal em tecidos); 3) A radiografia frequentemente não mostra cavitações (que dependem da resposta inflamatória do hospedeiro) e apresenta infiltrados intersticiais ou em campos médios/inferiores; 4) A disseminação hematogênica e o acometimento extrapulmonar são a regra. A anergia ao PPD é comum devido à falta de células para reagir ao antígeno.", "option_rationales": {"a": "Incorreta. Embora a forma seja disseminada, os granulomas em imunodeprimidos são tipicamente mal definidos e ricos em bacilos (multibacilares).", "b": "Incorreta. Cavitações são raras na imunodepressão grave pois exigem uma resposta imune exuberante para ocorrer a necrose e expulsão do caseum para a via aérea.", "c": "Correta. Resume precisamente a fisiopatologia da interação TB-HIV em estágios avançados.", "d": "Incorreta. O tratamento é o esquema RIPE padrão; o tempo de início da TARV é que deve ser manejado para evitar IRIS.", "e": "Incorreta. Como explicado, a falta de controle imunológico permite a proliferação desenfreada dos bacilos no tecido, tornando a lesão multibacilar."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["TB-HIV", "Imunoproficiência", "Fisiopatologia", "Infectologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 15), ('a15e5120-939d-499c-ba76-8ed71d87fe41', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um homem de 30 anos, natural da Bolívia e residente em regime de coabitação com outros 10 imigrantes em um dormitório no centro de São Paulo, apresenta febre vespertina e tosse produtiva há 6 semanas. O Teste Rápido Molecular (TRM-TB) detectou M. tuberculosis com resistência à rifampicina. De acordo com os protocolos vigentes para o tratamento da Tuberculose Resistente à Rifampicina (TB-RR) ou Multirresistente (TB-MDR) no Brasil, qual o esquema terapêutico inicial de escolha, desde que não haja contraindicações?", "options": {"a": "Esquema contendo Bedaquilina, Levofloxacino, Linezolida e Clofazimina por 6 a 9 meses (esquema curto oral).", "b": "Esquema RIPE estendido por 12 meses com adição de Estreptomicina nos primeiros 2 meses.", "c": "Substituição da Rifampicina pela Rifabutina, mantendo os demais fármacos do esquema primário.", "d": "Tratamento com esquema contendo Amicacina injetável diária por 6 meses associada a Etambutol e Pirazinamida.", "e": "Uso isolado de Levofloxacino e Etionamida até a realização do teste de sensibilidade genotípico completo."}, "answer": "a", "rationale": "Recentemente, o Brasil e a OMS passaram a priorizar esquemas totalmente orais e mais curtos para TB-MDR/RR. O esquema padrão atual para casos sem resistência prévia documentada a fluoroquinolonas envolve o uso de Bedaquilina, Levofloxacino, Linezolida e Clofazimina. Este esquema substituiu os antigos protocolos que exigiam drogas injetáveis (como Amicacina/Estreptomicina), apresentando maior adesão e menores taxas de efeitos colaterais graves (como ototoxicidade e nefrotoxicidade).", "option_rationales": {"a": "Correta. É o esquema oral ''all-oral'' preconizado atualmente para resistência à rifampicina.", "b": "Incorreta. Se há resistência à rifampicina (viga mestra do RIPE), o esquema primário perde sua eficácia fundamental.", "c": "Incorreta. Há resistência cruzada quase total entre Rifampicina e Rifabutina; esta última é usada para evitar interações (ex: HIV), não para tratar resistência.", "d": "Incorreta. Drogas injetáveis (aminoglicosídeos) caíram para segunda linha devido à toxicidade.", "e": "Incorreta. O tratamento de resistência nunca deve ser feito com apenas duas drogas por risco de ampliação da resistência."}, "difficulty": "dificil", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["TB-MDR", "Resistência à Rifampicina", "Terapêutica Atualizada", "Bolívia/Imigração"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 16), ('e042615d-3a6e-45c9-8d40-e31dea3ab989', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Paciente de 25 anos, sem comorbidades, é diagnosticada com Tuberculose Peritoneal após investigação de ascite de início insidioso, associada a perda de peso e febre. Foi submetida a laparoscopia que demonstrou múltiplos ''implantes granulares'' esbranquiçados em peritônio parietal e visceral. A análise do líquido ascítico revelou exsudato linfocítico com ADA de 50 U/L. Durante o tratamento com o esquema RIPE, a paciente informa que deseja engravidar ou se há risco de falha do seu método contraceptivo atual (anticoncepcional oral combinado). Qual a orientação correta a ser fornecida pelo médico?", "options": {"a": "A Rifampicina acelera o metabolismo dos hormônios anticoncepcionais, reduzindo sua eficácia; deve-se recomendar o uso de métodos de barreira (camisinha) ou DIU durante o tratamento.", "b": "A Isoniazida inibe a absorção intestinal de estrogênios; recomenda-se dobrar a dose do anticoncepcional.", "c": "O esquema RIPE não interfere na eficácia dos anticoncepcionais orais.", "d": "A tuberculose peritoneal causa infertilidade definitiva por salpingite associada, tornando a anticoncepção desnecessária.", "e": "A Pirazinamida aumenta o risco de trombose em usuárias de anticoncepcionais, contraindicando o uso de ambos simultaneamente."}, "answer": "a", "rationale": "A Rifampicina é um potente indutor das enzimas do sistema citocromo P450 no fígado (especialmente CYP3A4). Isso aumenta a taxa de degradação da maioria dos esteroides contraceptivos (estrógenos e progestágenos), levando a níveis subestimados no sangue e risco real de gravidez indesejada. A orientação clássica no tratamento da TB é a substituição por métodos não hormonais ou de barreira.", "option_rationales": {"a": "Correta. É uma das interações medicamentosas mais importantes no manejo prático da tuberculose em mulheres no menacme.", "b": "Incorreta. O mecanismo da Isoniazida não é esse e ''dobrar a dose'' não é uma conduta validada e segura.", "c": "Incorreta. A interação é real e clinicamente significativa.", "d": "Incorreta. Embora a TB possa atingir as trompas (salpingite tuberculosa), a infertilidade não é garantidamente definitiva e não justifica suspender a proteção.", "e": "Incorreta. Não há essa associação direta de risco trombótico sinérgico descrita para a Pirazinamida."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Farmacologia", "Saúde da Mulher", "Interações", "Rifampicina"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 17), ('869aeb66-6911-402b-8544-0b393467eda6', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Em uma maternidade pública, uma puérpera é diagnosticada com Tuberculose Pulmonar bacilífera logo após o parto. Ela está muito preocupada com o bem-estar do seu recém-nascido (RN). Sobre o aleitamento materno e a prevenção da Tuberculose no RN neste cenário, qual a recomendação correta do Ministério da Saúde?", "options": {"a": "A amamentação deve ser mantida (com uso de máscara cirúrgica pela mãe), mas a vacinação com BCG no RN deve ser adiada e iniciada a quimioprofilaxia primária com Isoniazida ou Rifampicina por 3 meses.", "b": "A amamentação está estritamente contraindicada até que a mãe complete 2 meses de tratamento e tenha baciloscopia negativa.", "c": "O RN deve ser vacinado com BCG imediatamente ao nascer e afastado do contato com a mãe por 15 dias.", "d": "A mãe deve amamentar sem restrições, pois os anticorpos passados pelo leite protegem o bebê contra a TB.", "e": "Deve-se realizar o TRM-TB no mecônio do bebê para diagnosticar TB congênita antes de qualquer medida."}, "answer": "a", "rationale": "Em filhos de mães bacilíferas ao parto: 1) Não se vacina com BCG ao nascer (para não interferir com o PPD/IGRA posterior); 2) Inicia-se quimioprofilaxia primária (Isoniazida ou Rifampicina) por 3 meses; 3) Após 3 meses, realiza-se o PPD/IGRA. Se negativo, suspende-se a droga e vacina-se com BCG. Se positivo, mantém-se a droga por mais 3 meses (totalizando 6) e não vacina com BCG. O aleitamento é mantido com máscara e cuidados de higiene.", "option_rationales": {"a": "Correta. Reflete o protocolo nacional de proteção ao RN exposto.", "b": "Incorreta. A amamentação é incentivada devido aos benefícios nutricionais e imunológicos, com o uso de máscara pela mãe.", "c": "Incorreta. A vacinação precoce com BCG atrapalharia o seguimento diagnóstico posterior da criança e a proteção da quimioprofilaxia é superior no curto prazo.", "d": "Incorreta. O leite não transmite anticorpos protetores contra a TB (que exige imunidade celular), mas a proximidade física transmite o bacilo por via aérea.", "e": "Incorreta. Investigação no mecônio não faz parte do rastreio de TB no RN exposto pós-parto."}, "difficulty": "dificil", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Pediatria", "Maternidade", "BCG", "Profilaxia Primária"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 18), ('fca889ea-a2f3-41b5-b21a-c9e8f5a97771', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um paciente de 40 anos, com história de alcoolismo pesado, está no 2º mês de tratamento para tuberculose e apresenta quadro de fraqueza muscular nas pernas, ''queimação'' e formigamento nos pés. Refere que a sensação começou de forma insidiosa e é pior à noite. Ao exame físico, nota-se diminuição da sensibilidade vibratória e dolorosa em botas (membros inferiores). Qual o diagnóstico mais provável e a medida terapêutica para manejo desse efeito colateral?", "options": {"a": "Neuropatia periférica induzida pela Isoniazida; administrar Piridoxina (Vitamina B6).", "b": "Hepatotoxicidade oculta; solicitar dosagem de magnésio e potássio.", "c": "Síndrome de Guillain-Barré parainfecciosa; realizar punção lombar.", "d": "Mielotoxicidade pela Rifampicina; solicitar hemograma urgente.", "e": "Insuficiência venosa crônica; prescrever meias de compressão."}, "answer": "a", "rationale": "A Isoniazida interfere no metabolismo da Piridoxina (Vitamina B6), o que pode levar a um quadro de neuropatia periférica sensitiva, especialmente em grupos de risco (alcoólatras, diabéticos, gestantes, idosos e desnutridos). A suplementação profilática ou terapêutica com B6 é a conduta de escolha.", "option_rationales": {"a": "Correta. A neuropatia por isoniazida é um efeito colateral clássico e evitável com a reposição de B6.", "b": "Incorreta. Distúrbios eletrolíticos podem causar cãibras, mas o padrão ''em botas'' e a queimação são neuropáticos.", "c": "Incorreta. O Guillain-Barré é uma polirradiculoneuropatia aguda ascendente, predominantemente motora, diferente deste quadro crônico sensitivo.", "d": "Incorreta. A Rifampicina causa anemia hemolítica ou plaquetopenia, não sintomas sensitivos periféricos.", "e": "Incorreta. A insuficiência venosa causa edema e peso nas pernas, sem déficits sensitivos objetivos em botas."}, "difficulty": "facil", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Efeitos Adversos", "Isoniazida", "Vitamina B6", "Sistema Nervoso"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 19), ('19c46bf7-fa15-47e7-879c-cda8cc69b1e1', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um homem de 52 anos apresenta-se com artralgia intensa, acompanhada de edema e calor em primeira articulação metatarsofajângica (podagra) à direita. O paciente está no primeiro mês de tratamento para tuberculose. Qual fármaco do esquema RIPE está mais associado a este quadro clínico e por qual mecanismo?", "options": {"a": "Pirazinamida; por reduzir a excreção renal de ácido úrico, levando à hiperuricemia.", "b": "Etambutol; por induzir a produção endógena de cristais de pirofosfato de cálcio.", "c": "Isoniazida; por causar vasculite de pequenos vasos (pseudo-gota).", "d": "Rifampicina; pela ativação direta de macrófagos sinoviais.", "e": "Estreptomicina; por toxicidade direta na cartilagem articular."}, "answer": "a", "rationale": "A Pirazinamida inibe competitivamente a excreção tubular de ácido úrico, o que frequentemente causa hiperuricemia assintomática durante o tratamento. Em pacientes susceptíveis, pode desencadear crises agudas de gota (artrite gotosa). Se as dores forem leves e suportáveis, mantém-se a medicação com uso de analgésicos/anti-inflamatórios. Se a crise for grave ou persistente, a droga pode precisar de suspensão ou ajuste.", "option_rationales": {"a": "Correta. A gota induzida pela pirazinamida é um efeito secundário metabólico bem conhecido.", "b": "Incorreta. O Etambutol atinge o nervo óptico, não o metabolismo de cristais.", "c": "Incorreta. A isoniazida não causa esse tipo de reação inflamatória articular.", "d": "Incorreta. A Rifampicina não interfere fisiologicamente na sinóvia desta forma.", "e": "Incorreta. A estreptomicina atinge o sistema auditivo e renal."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Reumatologia", "Efeitos Adversos", "Pirazinamida", "Gota"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 20), ('5911502c-ac69-4afb-aa39-b3f7859301de', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Paciente de 65 anos, institucionalizada em asilo, apresenta quadro de confusão mental aguda e queda do estado geral. A investigação inicial com RX de tórax demonstrou opacidade em lobo inferior direito, inicialmente tratada como pneumonia bacteriana típica sem melhora após 7 dias de levofloxacino. Foi realizado TRM-TB em escarro induzido, que foi positivo. Sobre a tuberculose no idoso, é correto afirmar:", "options": {"a": "A apresentação clínica costuma ser insidiosa, podendo simular outras doenças crônicas ou demenciais, e os achados radiológicos frequentemente localizam-se em campos pulmonares médios e inferiores (típico de reativação no idoso).", "b": "O diagnóstico é facilitado pela presença constante de febre alta e sudorese noturna exuberante.", "c": "A prova tuberculínica (PPD) é invariavelmente positiva devido ao efeito ''booster'' da vacinação na infância.", "d": "O tratamento deve ser feito com doses reduzidas (meia dose) de Rifampicina em todos os pacientes acima de 60 anos.", "e": "A forma miliar é proibitiva nesta faixa etária devido à involução tímica."}, "answer": "a", "rationale": "Idosos frequentemente apresentam sintomas inespecíficos para TB (astenia, anorexia, confusão mental) em vez da tríade clássica de tosse/febre/sudorese. Radiologicamente, a reativação da infecção latente no idoso pode assumir padrões ''não cavitários'' e localizar-se em regiões inferiores do pulmão, o que muitas vezes leva ao diagnóstico errôneo de pneumonia bacteriana aspirativa ou comunitária comum.", "option_rationales": {"a": "Correta. O idoso é um grupo com ''máscara clínica'' para TB, exigindo alta suspeição.", "b": "Incorreta. Sintomas constitucionais clássicos podem estar ausentes ou atenuados.", "c": "Incorreta. A anergia cutânea é frequente no idoso pela imunossenescência.", "d": "Incorreta. O tratamento segue as doses padrão baseadas no peso; apenas se monitora mais rigorosamente a hepatotoxicidade.", "e": "Incorreta. A forma miliar pode ocorrer em qualquer idade, especialmente em indivíduos com imunidade celular reduzida como o idoso."}, "difficulty": "dificil", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Geriatria", "Infectologia", "Diagnóstico Diferencial"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 21), ('46eea6d3-713e-44f5-b8eb-d2105cb1fc12', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Qual a principal justificativa epidemiológica para o uso do ''Tratamento Diretamente Observado'' (TDO) na estratégia de controle da tuberculose no sistema de saúde brasileiro?", "options": {"a": "Garantir a adesão do paciente ao tratamento, visando alcançar a cura e interromper a cadeia de transmissão na comunidade, além de evitar o surgimento de cepas resistentes.", "b": "Reduzir o custo do tratamento, ao permitir o fracionamento das doses na unidade de saúde.", "c": "Evitar que o paciente compartilhe seus medicamentos com seus contatos intradomiciliares.", "d": "Permitir a realização de exames de sangue diários para monitorar a função hepática durante a tomada da dose.", "e": "O TDO é apenas obrigatório para pacientes com diagnóstico de Tuberculose Multirresistente."}, "answer": "a", "rationale": "O TDO é a base da estratégia DOTS (Directly Observed Treatment Short-course) recomendada pela OMS. O objetivo é assegurar que o paciente tome a medicação corretamente, pois o uso irregular é o maior vilão do controle da TB no mundo: causa falha de cura, mantém a transmissibilidade e favorece a seleção natural de bacilos resistentes às drogas disponíveis.", "option_rationales": {"a": "Correta. O TDO é uma medida de saúde pública e não apenas um cuidado individual.", "b": "Incorreta. O TDO pode até ser mais caro logisticamente (exige profissional), mas o custo da ''não cura'' e da multirresistência é infinitamente maior.", "c": "Incorreta. O objetivo não é o controle de ''estoque'', mas a garantia da ingestão pelo paciente índice.", "d": "Incorreta. Não se faz controle laboratorial diário no TDO.", "e": "Incorreta. O TDO é recomendado para TODOS os casos de tuberculose, sensível ou resistente, na atenção primária."}, "difficulty": "facil", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Saúde Pública", "TDO", "Estratégia de Controle", "Adesão"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 22), ('75f8c38c-ce65-4adf-9d1f-4fd1a8bdf59d', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um paciente de 44 anos está tratando Tuberculose em esquema RIPE. Ele conta ao médico que seu suor, suas lágrimas e sua urina estão apresentando uma coloração ''laranja-avermelhada'' há alguns dias. De acordo com o conhecimento farmacológico, qual fármaco causa essa alteração e qual a orientação correta?", "options": {"a": "Rifampicina; orientar que é um efeito inofensivo esperado da eliminação da droga e não exige suspensão.", "b": "Isoniazida; suspender o tratamento por risco de hemólise intravascular aguda.", "c": "Pirazinamida; solicitar exames de função renal pois indica acúmulo de metabólitos.", "d": "Etambutol; indica toxicidade ocular iminente e exige consulta com oftalmologista.", "e": "Não é um efeito esperado; investigar sangramento oculto em vias urinárias e glândulas lacrimais."}, "answer": "a", "rationale": "A Rifampicina e seus metabólitos possuem uma coloração natural avermelhada. Por ser eliminada por diversas secreções corporais (urina, suor, lágrimas, saliva), é comum que o paciente note essa alteração. É fundamental avisar o paciente no início do tratamento para evitar pânico ou interrupção do uso.", "option_rationales": {"a": "Correta. Orientação clássica de educação em saúde no tratamento da TB.", "b": "Incorreta. A Isoniazida não causa alteração de cor de fluidos.", "c": "Incorreta. Não há relação com falha renal ou metabólitos coloridos da pirazinamida.", "d": "Incorreta. A toxicidade ocular do etambutol não se manifesta por lágrimas coloridas.", "e": "Incorreta. É um efeito fisiológico esperado da droga."}, "difficulty": "facil", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Farmacocinética", "Rifampicina", "Educação em Saúde"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 23), ('05786b19-03e1-4f83-b5b6-d8d08155c7c8', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Paciente de 37 anos, portador de insuficiência renal crônica (clearance de creatinina de 20 mL/min/1,73m²), inicia tratamento para TB. Sobre o ajuste de dose do esquema convencional para pacientes com disfunção renal severa, qual a recomendação atual?", "options": {"a": "Manter Rifampicina e Isoniazida em doses normais (eliminação predominantemente hepática) e aumentar o intervalo de administração da Pirazinamida e do Etambutol (ex: 3 vezes por semana).", "b": "Reduzir a dose de todos os fármacos em 50% de forma proporcional.", "c": "Suspender o Etambutol e substituí-lo por Estreptomicina.", "d": "Não são necessários ajustes pois as micobactérias possuem metabolismo independente da filtração glomerular.", "e": "Indicar apenas Rifampicina e Isoniazida por 12 meses."}, "answer": "a", "rationale": "Rifampicina e Isoniazida são metabolizadas e excretadas principalmente pelo fígado e bile, não exigindo ajuste em renais crônicos. Já o Etambutol e a Pirazinamida (ou seus metabólitos ativos) dependem da excreção renal; em pacientes com ClCr < 30 mL/min, a recomendação brasileira é de ajustar o intervalo para 3 vezes por semana (em vez de diário), visando evitar toxicidade acumulada.", "option_rationales": {"a": "Correta. Reflete o manejo técnico do paciente renal na TB.", "b": "Incorreta. A redução proporcional não considera a via de eliminação distinta de cada droga.", "c": "Incorreta. A Estreptomicina é nefrotóxica e estritamente contraindicada ou usada com extremo cautela em renais crônicos.", "d": "Incorreta. Os ajustes são cruciais para a segurança do hospedeiro, não pelo efeito na bactéria.", "e": "Incorreta. O esquema seria insuficiente para garantir a cura e evitar resistência sem as outras drogas."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Nefrologia", "Farmacologia Aplicada", "Insuficiência Renal"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 24), ('f5b9fbf4-0af5-4991-b018-60ea19fd966a', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Homem de 41 anos, sabidamente portador de HIV (CD4: 350 células/mm³), descobre tuberculose e inicia o esquema RIPE. Ele já utiliza TARV com o esquema Tenofovir, Lamivudina e Dolutegravir (TDF/3TC/DTG). Devido à potente indução enzimática da Rifampicina sobre o Dolutegravir, qual o ajuste laboratorial e medicamentoso obrigatório neste paciente?", "options": {"a": "Aumentar a dose do Dolutegravir para 50 mg de 12 em 12 horas.", "b": "Substituir o Dolutegravir por Efavirenz (600 mg ao dia).", "c": "Substituir a Rifampicina pela Rifabutina, mantendo o Dolutegravir 50 mg uma vez ao dia.", "d": "Apenas monitorar a carga viral do HIV mensalmente; não são necessários ajustes iniciais.", "e": "Suspender a TARV durante a fase de ataque da tuberculose (primeiros 2 meses)."}, "answer": "a", "rationale": "A Rifampicina induz o metabolismo do Dolutegravir (um inibidor de integrase), reduzindo significativamente seu nível terapêutico. Para compensar essa indução em pacientes usando Rifampicina, a dose do DTG deve ser dobrada (50 mg BID - 12/12h). A opção de trocar por Rifabutina (C) também existe, mas exige que o serviço tenha o medicamento disponível (que é mais caro e menos acessível que o ajuste de dose do DTG no SUS).", "option_rationales": {"a": "Correta. É a conduta operacional padrão no protocolo de co-infecção TB-HIV no Brasil de 2024.", "b": "Incorreta. O Dolutegravir é superior ao Efavirenz em eficácia e menos tóxico; o ajuste de dose permite mantê-lo.", "c": "Incorreta. Embora a Rifabutina tenha menos interação, o ajuste do DTG é a conduta primária mais comum no sistema público pelo custo.", "d": "Incorreta. O paciente sofreria falha virológica do HIV rapidamente sem o ajuste.", "e": "Incorreta. A suspensão da TARV em quem já a utiliza aumenta a mortalidade e o risco de doenças oportunistas."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["TB-HIV", "Infectologia", "Farmacodinâmica", "Dolutegravir"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 25), ('0ae9a6a9-9219-44bb-be8a-7d2bb16caff6', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Sobre o manejo da Infecção Latente por Tuberculose (ILTB) em pacientes que iniciarão uso de drogas imunobiológicas (como Anti-TNF, ex: Infliximabe), qual a conduta correta no Brasil?", "options": {"a": "Realizar PPD ou IGRA para todos; se PPD ≥ 5 mm (ou IGRA positivo), deve-se iniciar o tratamento preventivo da TB (TPTB) e aguardar, preferencialmente, pelo menos 1 mês de tratamento antes de iniciar o biológico.", "b": "O tratamento preventivo só deve ser iniciado se o PPD for superior a 15 mm, devido ao baixo risco dos Anti-TNF.", "c": "Se o paciente for vacinado com BCG, o PPD deve ser ignorado e o tratamento preventivo iniciado para todos os pacientes independente do teste.", "d": "Biológicos não exigem triagem para TB pois agem apenas na inflamação articular/intestinal.", "e": "O tratamento da ILTB nesses pacientes deve ser feito obrigatoriamente com o esquema RIPE completo por 6 meses."}, "answer": "a", "rationale": "Os inibidores de TNF-alfa bloqueiam uma citocina crucial para a manutenção do granuloma que ''aprisiona'' o bacilo da TB. O início dessas drogas em portadores de ILTB causa reativação explosiva, frequentemente com formas disseminadas. A triagem com PPD (ponto de corte 5 mm) ou IGRA é obrigatória, e o TPTB deve idealmente ser iniciado 1 mês antes da primeira dose do biológico.", "option_rationales": {"a": "Correta. É o protocolo de segurança para uso de imunobiológicos.", "b": "Incorreta. O risco com Anti-TNF é altíssimo; o corte de 5 mm visa não perder casos de infecção silenciosa.", "c": "Incorreta. O protocolo prevê a realização do teste; o tratamento ''cego'' não é preconizado.", "d": "Incorreta. Como explicado, o TNF é essencial para conter o M. tuberculosis.", "e": "Incorreta. O tratamento de infecção LATENTE é feito com monoterapia (Isoniazida) ou Rifampicina, não com RIPE."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["ILTB", "Imunobiológicos", "SEGURANÇA", "Protocolo"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 26), ('b8670275-90f9-422d-80d8-2fb8dd8781f3', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A Tuberculose Osteoarticular (Mal de Pott) atinge frequentemente a coluna vertebral. Qual o mecanismo de dor e a deformidade clássica esperada no exame físico deste paciente?", "options": {"a": "Dor nas costas insidiosa e deformidade em gibosidade (cifose angular) por colapso dos corpos vertebrais anteriores.", "b": "Dor súbita e escoliose severa por espasmo da musculatura paravertebral.", "c": "Pseudoartrose cervical e pescoço rígido por fusão atlanto-axial.", "d": "Lombalgia puramente mecânica sem alterações na inspeção estática.", "e": "Hiperlordose lombar compensatória por fraqueza dos glúteos."}, "answer": "a", "rationale": "O Mal de Pott é a tuberculose vertebral. O bacilo causa necrose caseosa e destruição do tecido ósseo, geralmente começando na parte anterior do corpo vertebral e se espalhando para o disco intervertebral. O colapso da porção anterior das vértebras leva à deformidade em cifose angular, chamada de ''giba'', que é o marco visual da doença avançada ou sequelar.", "option_rationales": {"a": "Correta. A gibosidade é o achado clássico do Mal de Pott.", "b": "Incorreta. A instalação é tipicamente lenta (meses), não súbita.", "c": "Incorreta. A TB vertebral atinge mais frequentemente a transição toracolombar, não a região cervical alta.", "d": "Incorreta. Em fases avançadas, a deformidade é evidente.", "e": "Incorreta. Como há colapso vertebral anterior, a deformidade é em flexão (cifose), não em extensão (lordose)."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Tuberculose Óssea", "Mal de Pott", "Ortopedia", "Infectologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 27), ('bff6faee-46c2-46c8-9bb4-47d94979caac', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um paciente de 46 anos, diagnosticado com tuberculose pulmonar há 2 meses, apresenta melhora total da tosse e da febre. Ele está muito feliz com o resultado e pergunta se já pode parar de tomar os remédios. Qual a justificativa científica correta para completar os 6 meses de tratamento?", "options": {"a": "O bacilo da TB possui diferentes populações metabólicas; os remédios matam rapidamente os bacilos em replicação ativa (fase de ataque), mas os bacilos ''persistentes'' ou dormentes exigem tempo prolongado (fase de manutenção) para serem eliminados e evitar recidivas.", "b": "É necessário esse tempo para que o corpo crie anticorpos (IgG) protetores contra novas infecções.", "c": "A medicação precisa se acumular no tecido gorduroso para ter efeito residual por 5 anos.", "d": "Se parar agora, ele desenvolverá alergia grave aos fármacos caso precise usá-los novamente no futuro.", "e": "Os 6 meses são um critério administrativo da OMS para facilitar a contagem de estatísticas de cura."}, "answer": "a", "rationale": "O M. tuberculosis cresce em diferentes nichos e velocidades. A fase de ataque (2 meses) elimina os bacilos de crescimento rápido (reduzindo a carga bacilar e a transmissibilidade). No entanto, existem populações de bacilos em ''semidormência'' (crescimento lento ou intermitente) dentro dos granulomas ou macrófagos. Somente a fase de manutenção prolongada consegue erradicar esses ''persisters'', garantindo a cura esterilizante e prevenindo que a doença retorne após o fim do tratamento (recidiva).", "option_rationales": {"a": "Correta. Explica a fundamentação biológica do tempo de tratamento.", "b": "Incorreta. A proteção contra a TB não é mediada por anticorpos circulantes (imunidade humoral).", "c": "Incorreta. O fármaco não funciona por acúmulo em gordura, mas por ação bactericida/bacteriostática direta nas populações bacilares.", "d": "Incorreta. O risco principal não é a alergia, mas a falha de cura e a resistência.", "e": "Incorreta. Os 6 meses foram definidos por rigorosos estudos clínicos (estudos de Madras, etc.) para minimizar recidivas."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Fisiopatologia", "Manejo Clínico", "Aderência", "Microbiologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 28), ('ee73a690-90a6-4781-8d2f-3bc2f8de2337', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Qual a conduta recomendada para um profissional de saúde que apresenta um PPD inicial negativo ao ser admitido em um hospital de referência para tuberculose, mas que após 1 ano de trabalho apresenta conversão para PPD positivo (12 mm)? O profissional está totalmente assintomático e tem RX de tórax normal.", "options": {"a": "Realizar diagnóstico de Infecção Latente por Tuberculose (conversão tuberculínica recente) e iniciar tratamento preventivo da TB (TPTB).", "b": "Apenas afastar o profissional do contato com pacientes até que o PPD negative.", "c": "Internação imediata para isolamento respiratório em quarto com pressão negativa.", "d": "Repetir o PPD em 15 dias; se mantiver 12 mm, realizar broncoscopia.", "e": "Considerar portador de TB-MDR e iniciar esquema especial com bedaquilina."}, "answer": "a", "rationale": "A ''conversão tuberculínica'' (um PPD que era negativo e passa a ser positivo, com incremento de pelo menos 10 mm em relação ao teste anterior num intervalo de até 2 anos) indica uma infecção RECENTE. Em profissionais de saúde, isso implica um altíssimo risco de progressão para doença ativa no curto prazo. Como os sintomas e o RX são negativos, o diagnóstico é ILTB e o tratamento preventivo é mandatório para proteção do trabalhador.", "option_rationales": {"a": "Correta. Conversão em profissional exposto é indicação formal de TPTB.", "b": "Incorreta. O PPD raramente negativa; o afastamento não trata a infecção já estabelecida.", "c": "Incorreta. Ele não tem doença ativa (é assintomático com RX normal) e não transmite o bacilo.", "d": "Incorreta. Não há sentido em repetir em 15 dias e a broncoscopia é desnecessária em assintomático com RX normal.", "e": "Incorreta. Não se assume resistência sem evidência genotípica ou falha de tratamento prévio."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Vigilância Ocupacional", "ILTB", "Infectologia", "PPD"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 29), ('bcf5f462-21ff-4d67-8ba9-e8274f9886a7', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um homem de 33 anos, com diagnóstico de Tuberculose Pulmonar bacilífera, iniciou o esquema RIPE há 10 dias. Ele retorna à Unidade Básica de Saúde queixando-se de náuseas leves e anorexia matinal, mas nega vômitos, icterícia ou dor abdominal. Ao exame físico: anictérico, eupneico e sem visceromegalias. Foram solicitados exames admissionais que mostram: TGO = 85 U/L (VR: < 40), TGP = 90 U/L (VR: < 40) e Bilirrubinas Totais = 0,9 mg/dL. Qual a conduta mais adequada perante este quadro de possível hepatotoxicidade inicial?", "options": {"a": "Manter o esquema RIPE inalterado, realizar orientações dietéticas e repetir os exames de função hepática em 15 dias para monitoramento.", "b": "Suspender imediatamente a Rifampicina e a Isoniazida e iniciar esquema alternativo com Etambutol e Estreptomicina.", "c": "Internar o paciente para biópsia hepática imediata devido ao risco de insuficiência hepática fulminante.", "d": "Apenas suspender a Pirazinamida, por ser o fármaco mais hepatotóxico das quatro drogas.", "e": "Dobrar a dose de Isoniazida para acelerar a cura e reduzir o tempo de exposição hepática."}, "answer": "a", "rationale": "A elevação assintomática das transaminases (até 3 ou 5 vezes o valor de referência, dependendo da presença ou não de sintomas) é comum no início do esquema RIPE e não exige a suspensão dos fármacos. Como o paciente tem elevação leve (cerca de 2 vezes o VR) e sintomas gastrointestinais muito discretos (sem icterícia ou dor), a conduta correta é a observação clínica próxima e repetição dos exames em duas semanas. A suspensão só é mandatória se: 1) Transaminases > 3x VR com sintomas; 2) Transaminases > 5x VR mesmo assintomático ou 3) Icterícia clínica.", "option_rationales": {"a": "Correta. Reflete o critério de segurança para manutenção do tratamento primário.", "b": "Incorreta. A suspensão precoce sem critérios laboratoriais/clínicos suficientes prejudica o tratamento da TB.", "c": "Incorreta. Não há sinais de gravidez ou insuficiência hepática que justifiquem medida invasiva.", "d": "Incorreta. Embora a Pirazinamida seja hepatotóxica, não se retira apenas uma droga do esquema fixo (4 em 1) sem necessidade absoluta.", "e": "Incorreta. Dobrar a dose aumentaria drasticamente o risco de necrose hepática por metabólitos da isoniazida."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Hepatotoxicidade", "Efeitos Adversos", "Manejo Clínico", "Infectologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 30), ('b072397e-4847-49fb-8093-0065a8d7fde3', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Sobre o diagnóstico da Tuberculose Pleural, analise as afirmativas abaixo e assinale a alternativa que contém a sequência correta de verdadeiro (V) ou falso (F):\n\n( ) O líquido pleural na TB é tipicamente um exsudato, com predominância de polimorfonucleares na fase crônica.\n( ) A dosagem de Adenosina Deaminase (ADA) possui alto valor preditivo negativo; se < 40 U/L, a chance de ser TB pleural é muito baixa.\n( ) A biópsia pleural por agulha (ex: agulha de Cope) tem maior sensibilidade diagnóstica que a baciloscopia direta do líquido pleural.\n( ) A presença de células mesoteliais em grande quantidade (> 5%) no líquido pleural reforça o diagnóstico de tuberculose.", "options": {"a": "V, V, F, F", "b": "F, V, V, F", "c": "F, F, V, V", "d": "V, F, V, F", "e": "F, V, F, V"}, "answer": "b", "rationale": "Análise das sentenças: 1) Falso: O líquido é exsudato, mas a predominância é linfocítica (não polimorfonuclear); 2) Verdadeiro: O ADA é excelente para exclusão (VPN alto); 3) Verdadeiro: A biópsia pleural pleural atinge 70-80% de sensibilidade (vê granulomas/caseum), enquanto a baciloscopia do líquido é raramente positiva (< 5-10%); 4) Falso: A tuberculose pleural causa uma reação fibrinosa que ''bloqueia'' o mesotélio, sendo característica a escassez ou ausência de células mesoteliais.", "option_rationales": {"a": "Incorreta. Falha no perfil celular e na biópsia.", "b": "Correta. Sequência exata baseada nos critérios de Light e histopatologia da TB.", "c": "Incorreta. Falha no ADA e na biópsia.", "d": "Incorreta. Falha generalizada em imunoliquidologia.", "e": "Incorreta. Falha na correlação biópsia x mesotélio."}, "difficulty": "dificil", "subspecialty": "Pneumologia", "subject": "Tuberculose", "tags": ["TB Pleural", "Líquido Pleural", "ADA", "Biópsia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 31), ('fe02a40c-26b7-4d2a-99c1-136d2da74ec6', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Paciente de 19 anos, hígido, realiza exame admissional e apresenta PPD de 18 mm. O RX de tórax é normal e o paciente é completamente assintomático. Informa que foi vacinado com BCG ao nascer (possui cicatriz). De acordo com as normas de 2024 do Ministério da Saúde, qual a abordagem correta para este caso?", "options": {"a": "Diagnosticar Infecção Latente por Tuberculose (ILTB) e indicar Tratamento Preventivo (TPTB) com Rifampicina (4 meses) ou Isoniazida (6-9 meses).", "b": "Considerar PPD falso-positivo pela vacinação com BCG na infância e liberar para o trabalho sem intervenção.", "c": "Realizar teste de escarro induzido para confirmar baciloscopia positiva oculta.", "d": "Indicar repetição da vacina BCG para reforçar a imunidade, já que o PPD está alto.", "e": "Solicitar tomografia de tórax de alta resolução; se normal, descartar qualquer infecção."}, "answer": "a", "rationale": "Um PPD ≥ 5 mm (ou ≥ 10 mm em alguns contextos, mas no Brasil adota-se o corte de 5 mm para contatos e grupos de risco) em indivíduo assintomático com RX normal define Infecção Latente. A cicatriz de BCG feita ao nascer não justifica um PPD de 18 mm aos 19 anos (o efeito da vacina no teste costuma desaparecer nos primeiros anos de vida). Por ser jovem e ter teste claramente positivo, há benefício em tratar a ILTB para reduzir o risco de adoecimento futuro.", "option_rationales": {"a": "Correta. Conduta preventiva padrão para ILTB.", "b": "Incorreta. Atribuir um PPD de 18 mm apenas à BCG neonatal é um erro comum que negligencia a infecção real.", "c": "Incorreta. Se o RX é normal e o paciente é assintomático, não há indicação de pesquisa de bacilo em escarro (não é doença ativa).", "d": "Incorreta. Não se faz reforço de BCG em adultos, muito menos com PPD positivo.", "e": "Incorreta. A TC é desnecessária se o RX for de boa qualidade e normal, pois o diagnóstico latente é imunobiológico, não de imagem."}, "difficulty": "media", "subspecialty": "Clínica Médica", "subject": "Tuberculose", "tags": ["ILTB", "BCG", "Epidemiologia", "Saúde Ocupacional"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 32), ('2968df0e-e698-461b-bcb8-ec0e65c21aab', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um paciente em tratamento para Tuberculose Pulmonar apresenta, subitamente, piora da acuidade visual bilateral, informando que as cores parecem ''desbotadas'' (especialmente o verde e o vermelho). Ao exame oftalmológico, nota-se neurite óptica retrobulbar. Qual droga do esquema RIPE deve ser suspensa imediatamente e qual a conduta para este efeito adverso?", "options": {"a": "Etambutol; suspender a droga definitivamente.", "b": "Isoniazida; suspender e substituir por Rifabutina.", "c": "Rifampicina; manter a droga e usar colírio de corticoide.", "d": "Pirazinamida; ajustar a dose para o peso ideal.", "e": "O quadro não está relacionado às drogas da TB; investigar glaucoma agudo."}, "answer": "a", "rationale": "A neurite óptica (com alteração na percepção de cores e perda de campo visual central) é o efeito colateral mais grave e característico do Etambutol. Frequentemente é dose-dependente e ocorre mais em pacientes com falha renal. Uma vez diagnosticada a toxicidade ocular, o fármaco deve ser suspenso de forma definitiva para evitar a cegueira irreversível.", "option_rationales": {"a": "Correta. Reconhecimento imediato do efeito tóxico clássico do Etambutol.", "b": "Incorreta. A Isoniazida causa neuropatia periférica e psicose, raramente neurite óptica isolada.", "c": "Incorreta. A Rifampicina não atinge o nervo óptico desta maneira.", "d": "Incorreta. A Pirazinamida atinge o fígado e o metabolismo do ácido úrico.", "e": "Incorreta. É um efeito adverso medicamentoso bem documentado no tratamento da TB."}, "difficulty": "facil", "subspecialty": "Oftalmologia", "subject": "Tuberculose", "tags": ["Etambutol", "Toxicidade Ocular", "Farmacovigilância"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 33), ('53b226d7-cfb2-4cda-9f25-aaf404117020', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Durante uma investigação de surto de Tuberculose em uma prisão, um detento apresenta tosse há 2 semanas. Realizado Teste Rápido Molecular (TRM-TB) que resultou: ''Detectado M. tuberculosis - Baixa Carga - Resistência à Rifampicina Detectada''. O serviço de saúde local decide realizar a cultura e o Teste de Sensibilidade Genotípico por Sonda (LPA) para investigar resistência de segunda linha. O LPA demonstrou resistência adicional ao Levofloxacino e Moxifloxacino. Qual a classificação correta desta cepa de tuberculose?", "options": {"a": "Tuberculose com resistência estendida (Pre-XDR).", "b": "Tuberculose Multirresistente (TB-MDR).", "c": "Tuberculose Extremamente Resistente (XDR-TB).", "d": "Tuberculose com resistência monodroga (TB-MR).", "e": "Tuberculose sensível atípica."}, "answer": "a", "rationale": "Definições da OMS/Ministério da Saúde: 1) TB-RR: Resistente apenas à rifampicina; 2) TB-MDR: Resistente a Rifampicina E Isoniazida; 3) Pre-XDR: Resistente a Rifampicina E a qualquer Fluoroquinolona (Levofloxacino/Moxifloxacino); 4) XDR: Resistente a Rifampicina, Fluoroquinolonas E pelo menos uma droga de grupo A (Bedaquilina ou Linezolida). No caso, a resistência à Rifampicina + Fluoroquinolona caracteriza a Pre-XDR.", "option_rationales": {"a": "Correta. Reflete a nova nomenclatura para cepas com resistência a quinolonas.", "b": "Incorreta. TB-MDR é a base para as outras resistências, mas o termo Pre-XDR é mais específico para este caso.", "c": "Incorreta. Para ser XDR, precisaria de resistência a Bedaquilina ou Linezolida.", "d": "Incorreta. Houve resistência a pelo menos duas classes (Rifa + Quinolona).", "e": "Incorreta. Não existe este termo para resistências detectadas."}, "difficulty": "dificil", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Resistência Bacteriana", "Pre-XDR", "Infectologia", "Sistema Prisional"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 34), ('6409763e-1847-4943-a645-f44f4544ba5d', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um paciente portador de Hepatite C crônica com cirrose Child-Pugh B é diagnosticado com Tuberculose Pulmonar. Perante o alto risco de falência hepática com o esquema RIPE convencional, qual a recomendação de esquema terapêutico alternativo com menor carga hepatotóxica?", "options": {"a": "Esquema sem Pirazinamida: Rifampicina + Isoniazida + Etambutol por 9 meses.", "b": "Esquema com substituição de todas as drogas por Estreptomicina e Amicacina.", "c": "Tratamento apenas com Levofloxacino por 18 meses.", "d": "Manter o RIPE e associar Silimarina para proteção hepatocitária.", "e": "Aguardar o tratamento da Hepatite C antes de iniciar o da Tuberculose."}, "answer": "a", "rationale": "A Pirazinamida é a droga mais hepatotóxica do esquema RIPE e a primeira a ser retirada em hepatopatas graves. O esquema 2 RIE / 7 RI (9 meses de duração total) é a alternativa preferencial para cirróticos Child B ou C, pois exclui a pirazinamida mas mantém a Rifampicina e Isoniazida, garantindo alta taxa de cura.", "option_rationales": {"a": "Correta. Manejo de hepatopatas graves na TB.", "b": "Incorreta. Esquemas puramente injetáveis são tóxicos e menos eficazes que o RIE.", "c": "Incorreta. Monoterapia com quinolona gera resistência rápida.", "d": "Incorreta. A Silimarina não anula a toxicidade direta da pirazinamida no parênquima cirrótico.", "e": "Incorreta. A tuberculose é uma doença aguda e infectocontagiosa que exige tratamento imediato."}, "difficulty": "media", "subspecialty": "Hepatologia", "subject": "Tuberculose", "tags": ["Cirrose", "Hepatotoxicidade", "Esquemas Especiais", "Child-Pugh"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 35), ('265d5e83-66fb-4ff9-adc3-4b5ac1ccba8a', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um escolar de 8 anos apresenta emagrecimento, febre diária não aferida há 1 mês e tosse seca persistente. O contato intradomiciliar é o tio, que trata TB pulmonar bacilífera. O RX de tórax da criança mostra ''alargamento do mediastino por linfonodomegalia hilar direita''. O PPD é de 12 mm. De acordo com o sistema de escore para diagnóstico de TB na infância (Ministério da Saúde), qual a pontuação aproximada e a conduta sugerida?", "options": {"a": "40 pontos ou mais (Diagnóstico muito provável); iniciar tratamento com esquema RIPE (doses pediátricas).", "b": "10 pontos (Diagnóstico pouco provável); realizar broncoscopia para biópsia.", "c": "25 pontos (Diagnóstico possível); colher 3 amostras de escarro induzido para confirmar.", "d": "0 pontos; o tio é que deve ser investigado, não a criança.", "e": "30 pontos (Diagnóstico provável); realizar TC de crânio antes de tratar."}, "answer": "a", "rationale": "O sistema de escore considera: 1) Quadro clínico (febre/tosse/perda de peso) = 15 pontos; 2) RX de tórax com linfonodomegalia (imagem sugestiva) = 15 pontos; 3) Contato com adulto bacilífero = 10 pontos; 4) PPD positivo = 10 a 15 pontos. No caso, a criança soma > 40 pontos. Pelo protocolo, em crianças com > 40 pontos, o diagnóstico é MUITO PROVÁVEL e o tratamento pode ser iniciado sem necessidade de confirmação bacteriológica (difícil na infância).", "option_rationales": {"a": "Correta. Aplicação prática do escore de diagnóstico infantil.", "b": "Incorreta. Subestima gravemente os achados clínicos e epidemiológicos.", "c": "Incorreta. Embora o escarro possa ser colhido, não se deve retardar o tratamento com esta pontuação.", "d": "Incorreta. A criança é sintomática e tem critérios claros de infecção/doença.", "e": "Incorreta. A TC de crânio não tem indicação clínica neste quadro puramente pulmonar/mediastinal."}, "difficulty": "media", "subspecialty": "Pediatria", "subject": "Tuberculose", "tags": ["TB Infantil", "Escore de Diagnóstico", "Pediatria", "Saúde da Família"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 36), ('e20c5a2b-7101-4009-9a4d-d37bbe06a2a3', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Sobre a Tuberculose Miliar, assinale a alternativa que descreve corretamente o padrão radiológico típico e o mecanismo fisiopatológico principal.", "options": {"a": "Micronódulos difusos (1-3 mm) distribuídos uniformemente em ambos os pulmões; reflexo de disseminação hematogênica massiva do bacilo.", "b": "Grandes cavitações em ápices pulmonares; reflexo de hipersensibilidade tardia exuberante.", "c": "Consolidação lobar com broncograma aéreo; reflexo de disseminação broncogênica.", "d": "Derrame pleural bilateral e massivo; reflexo de insuficiência cardíaca direita associada à TB.", "e": "Fibrose pulmonar extensa em campos médios; reflexo de cura espontânea sem tratamento."}, "answer": "a", "rationale": "A TB miliar recebe esse nome pela semelhança das lesões com sementes de milho (millet). Ocorre quando um foco caseoso se rompe para dentro de um vaso sanguíneo, espalhando milhões de bacilos pela circulação sistêmica. O resultado são milhões de pequenos granulomas (micronódulos) que se depositam nos pulmões e outros órgãos (fígado, baço, medula óssea). É uma forma grave e potencialmente fatal.", "option_rationales": {"a": "Correta. Definição clássica radiológica e patogênica da forma miliar.", "b": "Incorreta. Cavitações são típicas da forma pós-primária localizada.", "c": "Incorreta. Padrão de consolidação é de pneumonia comum; a TB pode causar, mas não é o padrão ''miliar''.", "d": "Incorreta. Embora o derrame possa ocorrer, os micronódulos são o achado definidor.", "e": "Incorreta. A TB miliar não cura espontaneamente; evolui para óbito se não tratada."}, "difficulty": "facil", "subspecialty": "Radiologia", "subject": "Tuberculose", "tags": ["TB Miliar", "Radiologia", "Fisiopatologia", "Infectologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 37), ('61d15f2a-ec04-4f63-8e80-459907e02dfa', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Paciente de 42 anos apresenta quadro clínico de tosse crônica e hemoptise. O teste rápido molecular (TRM-TB) detecta M. tuberculosis sensível à rifampicina. No entanto, após 3 meses de tratamento com o esquema RIPE e boa adesão (TDO), o paciente mantém febre diária e a baciloscopia de escarro continua persistentemente positiva (2+). Qual a melhor conduta perante a suspeita de falência terapêutica?", "options": {"a": "Encaminhar para centro de referência, solicitar cultura com teste de sensibilidade genotípico/fenotípico e iniciar esquema especial para TB multirresistente.", "b": "Apenas repetir o esquema RIPE do zero, pois ele deve ter cuspido os remédios.", "c": "Aumentar a duração do tratamento para 12 meses, mantendo as mesmas drogas.", "d": "Indicar lobectomia pulmonar para retirada do foco persistente.", "e": "Trocar apenas a Rifampicina por Rifabutina."}, "answer": "a", "rationale": "A manutenção da positividade da baciloscopia no 3º ou 4º mês de tratamento adequado define FALÊNCIA TERAPÊUTICA. Isso geralmente indica que o bacilo é resistente às drogas do esquema primário ou que há um problema imunológico/absortivo severo. A conduta é a investigação de resistência em rede de referência e mudança para esquemas robustos para resistência (ex: TB-MDR).", "option_rationales": {"a": "Correta. Protocolo de manejo de falha ao esquema primário.", "b": "Incorreta. Repetir o mesmo esquema que já falhou é promover mais resistência.", "c": "Incorreta. Se o bacilo é resistente, o tempo de exposição não resolverá a infecção.", "d": "Incorreta. A cirurgia é reservada para sequelas ou complicações localizadas, não para tratamento de falha primária sem antes ajustar as drogas.", "e": "Incorreta. Trocar uma droga por outra da mesma classe não resolve a multirresistência."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Falência Terapêutica", "Resistência", "Manejo Clínico"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 38), ('48087634-4e6b-406f-a37c-11768a5ac1de', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um homem de 35 anos apresenta Tuberculose Ganglionar cervical (escrofulose). Foi iniciada medicação e, após 15 dias, os linfonodos que eram endurecidos tornaram-se flutuantes e drenaram espontaneamente material caseoso. O paciente desesperado procura o médico achando que a doença piorou. Qual a explicação e conduta correta?", "options": {"a": "Trata-se da evolução natural da TB ganglionar (coliquação); deve-se manter o esquema RIPE e realizar curativos locais.", "b": "Isso indica resistência bacteriana; trocar o tratamento para o esquema de resistência.", "c": "O paciente desenvolveu uma superinfecção bacteriana por Staphylococcus; adicionar Vancomicina venosa.", "d": "É uma reação alérgica à Pirazinamida; suspender todas as drogas.", "e": "Indicação cirúrgica imediata de esvaziamento cervical radical."}, "answer": "a", "rationale": "A TB ganglionar cursa com inflamação que pode evoluir para a necrose de liquefação (coliquação). O linfonodo ''amolece'' e pode drenar por fístulas na pele (escrofulodermia). Isso não significa obrigatoriamente falha do tratamento, mas sim o processo de expulsão do material necrótico. O tratamento medicamentoso deve continuar exatamente como está.", "option_rationales": {"a": "Correta. Evolução clínica clássica da forma ganglionar.", "b": "Incorreta. A drenagem de caseum é um fenómeno físico do granuloma, não sinal de resistência biológica.", "c": "Incorreta. Embora a infecção secundária possa ocorrer, a saída de material amarelado/esbranquiçado sem odor fétido ou inflamação aguda severa sugere caseum da TB.", "d": "Incorreta. Não há padrão de hipersensibilidade cutânea sugerido.", "e": "Incorreta. A cirurgia radical não é o tratamento primário para linfonodos tuberculosos coliquados."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["TB Ganglionar", "Escrofulose", "Caseum", "Infectologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 39), ('a85bf417-fd5a-474c-89ee-dd186b0c0d60', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Qual o achado tomográfico clássico que sugere a presença de disseminação broncogênica da tuberculose em um pulmão previamente cavitado?", "options": {"a": "Padrão de ''árvore em brotamento'' (tree-in-bud).", "b": "Vidro fosco difuso e homogêneo.", "c": "Placas pleurais calcificadas.", "d": "Padrão de ''pavimentação maluca'' (crazy paving).", "e": "Sinal do ''halo invertido''."}, "answer": "a", "rationale": "O sinal de ''árvore em brotamento'' na Tomografia de Alta Resolução representa o preenchimento de bronquíolos terminais por material mucoide, pus ou inflamação. Na TB, quando uma caverna drena seu conteúdo rico em bacilos para os brônquios, esse material ''escorre'' e entope os bronquíolos distais, criando esse aspecto de pequenos ramos com brotos na ponta, indicativo de atividade de doença e disseminação local.", "option_rationales": {"a": "Correta. Sinal radiológico clássico de disseminação broncogênica.", "b": "Incorreta. Vidro fosco é inespecífico e sugere edema ou inflamação alveolar leve.", "c": "Incorreta. Placas pleurais sugerem exposição ao asbesto.", "d": "Incorreta. Pavimentação maluca sugere proteinose alveolar ou certas pneumonias virais (ex: COVID-19).", "e": "Incorreta. Halo invertido é mais associado à pneumonia em organização ou paracoccidioidomicose."}, "difficulty": "media", "subspecialty": "Radiologia", "subject": "Tuberculose", "tags": ["Tomografia", "Árvore em Brotamento", "Radiologia", "Pneumologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 40), ('4fa4a6fc-37ca-4ea7-8403-c3409d0df23c', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Sobre o manejo da Tuberculose no Sistema Prisional brasileiro, é fundamental o rastreio sistemático de sintomas. Qual o critério de ''sintomático respiratório'' adotado especificamente para as populações privadas de liberdade e por que é diferente da população geral?", "options": {"a": "Presença de tosse por qualquer tempo (independentemente da duração); devido ao alto risco de transmissão em ambientes confinados.", "b": "Tosse por mais de 3 semanas; conforme padrão da OMS para países tropicais.", "c": "Tosse acompanhada obrigatoriamente de febre > 39°C.", "d": "Apenas aqueles que apresentam hemoptise franca.", "e": "Não há rastreio de tosse, apenas realização de RX de tórax anual para todos."}, "answer": "a", "rationale": "Em populações de alto risco e confinamento (como prisioneiros e moradores de rua), o critério de ''3 semanas de tosse'' é considerado muito tardio. Para evitar surtos massivos, qualquer pessoa que relate tosse (por qualquer tempo) deve ser considerada suspeita e investigada com TRM-TB ou baciloscopia imediatamente.", "option_rationales": {"a": "Correta. Estratégia de busca ativa agressiva em grupos vulneráveis.", "b": "Incorreta. Este é o critério para a população geral sem fatores de risco conhecidos.", "c": "Incorreta. A febre não é necessária para iniciar a investigação.", "d": "Incorreta. Hemoptise é sinal tardio; o objetivo é pegar casos precoces.", "e": "Incorreta. O rastreio clínico é a base do programa de controle prisional."}, "difficulty": "facil", "subspecialty": "Saúde Pública", "subject": "Tuberculose", "tags": ["Saúde Prisional", "Sintomático Respiratório", "Vigilância", "Epidemiologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 41), ('063dccc7-854b-4af4-b08c-6f1899d002cd', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Paciente de 25 anos, em tratamento para TB pulmonar há 1 mês, desenvolve quadro de icterícia (3+/4+), dor em hipocôndrio direito e vômitos persistentes. Transaminases: TGO = 550 U/L, TGP = 610 U/L. De acordo com o protocolo do Ministério da Saúde para hepatotoxicidade grave, qual a conduta imediata em relação ao esquema RIPE?", "options": {"a": "Suspender todas as drogas (R-I-P-E) imediatamente e aguardar a normalização dos sintomas e das enzimas (até queda < 2x VR) antes de reintroduzir.", "b": "Suspender apenas a Pirazinamida e manter as demais.", "c": "Trocar por esquema injetável com Estreptomicina e Gentamicina imediatamente.", "d": "Reduzir as doses pela metade até o paciente melhorar da cor amarelada.", "e": "Manter o tratamento e prescrever corticoide sistêmico para reduzir a inflamação hepática."}, "answer": "a", "rationale": "Icterícia e transaminases > 10x o valor de referência (ou > 5x com sintomas) configuram hepatite medicamentosa grave. A primeira medida é interromper TODO o tratamento (STOP RIPE). Após a melhora clínica e laboratorial evidente, as drogas serão reintroduzidas uma a uma, em ordem específica (Geralmente R -> I -> P ou esquemas alternativos se a toxicidade persistir).", "option_rationales": {"a": "Correta. Regra de ouro na segurança do tratamento da TB.", "b": "Incorreta. Na vigência de icterícia, não se arrisca manter nenhuma droga hepatotóxica (R e I também são).", "c": "Incorreta. Não se inicia tratamento de resistência no meio de uma hepatite medicamentosa aguda sem necessidade absoluta.", "d": "Incorreta. Subdose mantém a agressão hepática e gera resistência bacteriana.", "e": "Incorreta. Corticoides não tratam a causa (as drogas) e podem mascarar a gravidade da lesão."}, "difficulty": "media", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["Hepatotoxicidade", "Icterícia", "Manejo de Crise", "Infectologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 42), ('319cbac7-ea3b-430a-aac8-629c93f89bc8', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Um paciente de 50 anos, ex-tabagista, trata TB há 4 meses e apresenta imagem cavitária residual estável em lobo superior direito. Ele queixa-se de episódios recorrentes de hemoptise leve. A tomografia mostra uma ''massa arredondada móvel conforme decúbito'' dentro da antiga cavidade da TB, com o sinal do ''crescente aéreo'' (Monod sign). Qual o diagnóstico provável?", "options": {"a": "Aspergiloma (Bola fúngica).", "b": "Reativação da Tuberculose.", "c": "Abscesso pulmonar piogênico.", "d": "Carcinoma broncogênico escamoso.", "e": "Infarto pulmonar por TEP."}, "answer": "a", "rationale": "Cavidades antigas da tuberculose são locais ideais para a colonização por fungos do gênero Aspergillus. O fungo cresce formando uma massa de hifas e debris (bola fúngica) que fica solta dentro da cavidade. O sinal característico é o crescente de ar ao redor da massa arredondada. Clinicamente, a hemoptise recorrente é o sintoma cardinal, causada pela erosão mecânica dos vasos da parede da cavidade pela massa fúngica.", "option_rationales": {"a": "Correta. Complicação cavitária clássica da TB sequelar.", "b": "Incorreta. Reativação causaria novos infiltrados e sintomas sistêmicos (febre/sudorese).", "c": "Incorreta. Abscesso causa nível hidroaéreo e febre alta.", "d": "Incorreta. Câncer de pulmão pode cavitar, mas a ''bola móvel'' é muito típica do fungo.", "e": "Incorreta. TEP não costuma se manifestar como massa móvel intracavitária."}, "difficulty": "media", "subspecialty": "Pneumologia", "subject": "Tuberculose", "tags": ["Aspergiloma", "Sequela de TB", "Radiologia", "Pneumologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 43), ('000bed15-9745-4856-a05d-a27ea50e35b5', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Sobre a Tuberculose Genitourinária, qual o achado clássico no exame de urina (EAS/Tipo 1) que levanta a suspeita diagnóstica mesmo antes da cultura?", "options": {"a": "Piúria estéril (presença de leucócitos na urina com cultura bacteriana convencional negativa).", "b": "Hematúria macroscópica com cilindros hemáticos.", "c": "Glicosúria maciça sem hiperglicemia.", "d": "Cristais de oxalato de cálcio em grande quantidade.", "e": "Proteinúria nefrótica (> 3,5 g/dia)."}, "answer": "a", "rationale": "A presença sistemática de leucócitos na urina (pus) em um paciente com sintomas urinários crônicos (polaciúria, disúria), mas cujas culturas de urina para bactérias comuns (como E. coli) são sempre negativas, é chamada de ''piúria estéril''. Isso sugere que o agente causador é um germe que não cresce em meios comuns, sendo o M. tuberculosis a principal hipótese clínica a ser investigada com culturas em meio de Lowenstein-Jensen.", "option_rationales": {"a": "Correta. Signo clássico de TB urinária.", "b": "Incorreta. Sugere glomerulonefrite, não infecção por micobactéria.", "c": "Incorreta. Sugere síndrome de Fanconi ou diabetes, sem relação com TB.", "d": "Incorreta. Associado a cálculos renais (litíase).", "e": "Incorreta. Padrão de doença glomerular primária."}, "difficulty": "media", "subspecialty": "Urologia", "subject": "Tuberculose", "tags": ["TB Genitourinária", "Piúria Estéril", "Urologia", "Nefrologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 44), ('b0d07f8f-ebc1-4cad-8ee7-b6d71f1c6f12', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Qual a duração padrão do tratamento para Tuberculose do Sistema Nervoso Central (Meningoencefalite) e da Tuberculose Osteoarticular no Brasil?", "options": {"a": "12 meses; com uso associado de corticoide nos primeiros meses de tratamento da meningite.", "b": "6 meses; igual ao tratamento da forma pulmonar.", "c": "18 meses; devido à baixa penetração das drogas na barreira hematoencefálica.", "d": "24 meses; conforme protocolo de TB multirresistente.", "e": "9 meses; sem necessidade de corticoides."}, "answer": "a", "rationale": "Diferente da forma pulmonar (6 meses), as formas osteoarticular e de SNC exigem um tratamento prolongado de 12 meses (2 meses de RIPE + 10 meses de RI). Na meningite tuberculosa, o uso de corticoides (prednisona ou dexametasona) nas primeiras 4 a 8 semanas é fundamental para reduzir a resposta inflamatória no espaço subaracnóideo, prevenindo sequelas como hidrocefalia e vasculites cerebrais.", "option_rationales": {"a": "Correta. Duração e adjuvância preconizadas para formas graves/extrapulmonares selecionadas.", "b": "Incorreta. 6 meses é tempo insuficiente para estas localizações específicas.", "c": "Incorreta. 18 meses é excessivo para o esquema sensível.", "d": "Incorreta. 24 meses não é o padrão para casos sensíveis.", "e": "Incorreta. O corticoide é viga mestra na meningite TB para melhorar o prognóstico neurológico."}, "difficulty": "media", "subspecialty": "Neurologia", "subject": "Tuberculose", "tags": ["Meningite TB", "Terapêutica", "Corticosteroides", "Neurologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 45), ('b49d3567-7509-4b01-a4fc-95a6567c3aa4', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Sobre a imunologia da Tuberculose, o Teste de Liberação de Interferon-gama (IGRA) tem se tornado mais comum. Qual a principal vantagem do IGRA em relação ao teste cutâneo de PPD?", "options": {"a": "O IGRA não apresenta falso-positivo em pessoas vacinadas com BCG, pois utiliza antígenos específicos (ESAT-6 e CFP-10) que não estão presentes na cepa da vacina.", "b": "O IGRA é um teste de baixo custo que pode ser feito em qualquer farmácia.", "c": "O IGRA consegue diferenciar com clareza se a doença é latente ou se é ativa.", "d": "O IGRA não exige coleta de sangue, sendo feito através da saliva.", "e": "O IGRA é positivo apenas em pacientes com imunodepressão grave (HIV/AIDS)."}, "answer": "a", "rationale": "O IGRA é um teste ''in vitro'' que mede a resposta das células T ao M. tuberculosis. Ao contrário do PPD, que usa um ''pool'' de proteínas (PPD - Purified Protein Derivative) comuns a muitas micobactérias e à vacina BCG, o IGRA usa apenas proteínas específicas do bacilo selvagem. Portanto, um IGRA positivo indica infecção real, sem a interferência diagnóstica da vacinação prévia, o que é muito útil em países com alta cobertura vacinal como o Brasil.", "option_rationales": {"a": "Correta. Versa sobre a especificidade superior do IGRA.", "b": "Incorreta. O IGRA é um teste caro e exige laboratório especializado com tecnologia de ensaio ELISA.", "c": "Incorreta. Nem o PPD nem o IGRA conseguem diferenciar infecção latente de doença ativa; ambos indicam apenas que o corpo ''conhece'' o bacilo.", "d": "Incorreta. O IGRA é feito em sangue total colhido por venopunção.", "e": "Incorreta. O IGRA, assim como o PPD, pode ter sensibilidade reduzida em imunodeprimidos graves pela falta de resposta das células T."}, "difficulty": "media", "subspecialty": "Imunologia", "subject": "Tuberculose", "tags": ["IGRA", "PPD", "Diagnóstico Imunológico", "BCG"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 46), ('cf9db0bc-9f05-44df-8a61-98b66dac94c6', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciated": "Paciente de 29 anos, usuário de drogas injetáveis, admitido com dispneia e febre. O RX de tórax mostra múltiplos nódulos periféricos, alguns com cavitação central pequena, sugestivos de êmbolos sépticos. A baciloscopia de escarro é negativa (3 amostras). Foi realizada hemocultura que isolou Staphylococcus aureus. Sobre este caso e a exclusão de Tuberculose, é correto afirmar:", "options": {"a": "A presença de S. aureus não exclui a possibilidade de coinfecção com TB, especialmente em pacientes vulneráveis; deve-se considerar a realização de TRM-TB e biópsia das lesões se o quadro não regredir com antibióticos comuns.", "b": "Estafilococos e M. tuberculosis não coexistem no mesmo paciente devido à competição por substratos.", "c": "Toda lesão cavitária no pulmão é obrigatoriamente TB até que se prove o contrário.", "d": "O TRM-TB não deve ser feito em quem tem diagnóstico de bacteremia estafilocócica por risco de resultados falso-positivos por ''reação cruzada de capsídeos''.", "e": "A cavitação de êmbolos sépticos é patognomônica de tuberculose miliar."}, "answer": "a", "rationale": "O raciocínio clínico deve estar aberto a coinfecções ou diagnósticos diferenciais. Embora o foco agora seja a endocardite/êmbolos sépticos por S. aureus, a Tuberculose é endêmica e pode coexistir. O erro comum é parar a investigação ao encontrar o primeiro patógeno, negligenciando a TB em grupos de altíssimo risco (como usuários de drogas).", "option_rationales": {"a": "Correta. Demonstra prudência diagnóstica e consciência epidemiológica.", "b": "Incorreta. Não existe tal exclusão biológica competitiva.", "c": "Incorreta. Muitas doenças causam cavitação: fungos, câncer, abscessos piogênicos, êmbolos sépticos, granulomatose de Wegener, etc.", "d": "Incorreta. O TRM-TB é baseado em PCR (DNA), não tem reação cruzada com bactérias Gram-positivas como S. aureus.", "e": "Incorreta. TB miliar tipicamente NÃO causa macro-cavitações, mas sim micronódulos compactos."}, "difficulty": "media", "subspecialty": "Clínica Médica", "subject": "Tuberculose", "tags": ["Diagnóstico Diferencial", "Êmbolos Sépticos", "Co-infecção"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 47), ('65d1b97b-cd5f-4634-a9c7-c90f1dfdcbc0', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Qual a principal causa de resistência a múltiplas drogas (TB-MDR) no contexto do sistema de saúde?", "options": {"a": "Uso irregular da medicação pelo paciente ou prescrição inadequada de doses/tempos pelos profissionais (tratamento inadequado).", "b": "Mutação espontânea do bacilo causada pela poluição atmosférica.", "c": "Transmissão exclusiva por animais domésticos infectados.", "d": "Falta de vacinação com BCG em adultos.", "e": "Ingestão excessiva de laticínios não pasteurizados."}, "answer": "a", "rationale": "A resistência é um fenômeno de seleção natural induzido pelo homem. Quando o paciente toma o remédio de forma intermitente (alguns dias sim, outros não), os níveis da droga no sangue caem abaixo da dose letal. Isso mata os bacilos sensíveis, mas permite que os bacilos com mutações naturais de resistência sobrevivam e se proliferem, tornando o tratamento convencional ineficaz.", "option_rationales": {"a": "Correta. A falha de adesão é o motor da crise de multirresistência global.", "b": "Incorreta. Poluição não tem relação genética com a mutação do M. tuberculosis.", "c": "Incorreta. A TB humana (por M. tuberculosis) é transmitida de pessoa para pessoa por via aérea.", "d": "Incorreta. A BCG previne formas graves na infância, mas não tem relação direta com a prevenção de resistência de cepas em adultos.", "e": "Incorreta. Isso descreve a transmissão da TB bovina (M. bovis), que é rara e não é a causa da crise de MDR."}, "difficulty": "facil", "subspecialty": "Saúde Pública", "subject": "Tuberculose", "tags": ["Resistência", "Antropogenia", "Saúde Pública", "Adesão"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 48), ('cf540974-4390-40d3-ad0d-6ae0f48fb70a', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "No contexto da pandemia de HIV, a Tuberculose tornou-se a principal causa de óbito evitável. Sobre o ''rastreio da TB em indivíduos vivendo com HIV'', qual a ferramenta recomendada para diagnóstico em pacientes gravemente doentes e internados, mesmo que não consigam produzir escarro?", "options": {"a": "Teste de antígeno lipoarabinomanana na urina (LF-LAM).", "b": "Baciloscopia de secreção lacrimar.", "c": "Níveis de proteína C reativa ultrassensível.", "d": "Biópsia de medula óssea para todos os pacientes com HIV.", "e": "Aguardar a produção espontânea de escarro, independente do tempo."}, "answer": "a", "rationale": "O LF-LAM é um teste rápido feito na URINA que detecta um componente da parede celular do bacilo da TB (o lipoarabinomanano). Ele é indicado especificamente para pacientes com HIV avançado (CD4 < 200 ou muito doentes), pois nestes casos a carga bacilar é alta e o bacilo ''vaza'' para a urina. É uma ferramenta vital para diagnóstico rápido à beira do leito em pacientes que não conseguem fornecer amostras respiratórias.", "option_rationales": {"a": "Correta. Tecnologia inovadora incorporada para redução da mortalidade TB-HIV.", "b": "Incorreta. Não existe baciloscopia de lágrima como método diagnóstico padronizado.", "c": "Incorreta. A PCR é inespecífica e indica inflamação, não confirmando TB.", "d": "Incorreta. Seria uma medida invasiva desproporcional como rastreio inicial msm em HIV.", "e": "Incorreta. Retardar o diagnóstico em TB-HIV é fatal; deve-se usar métodos alternativos (induções, urina, biópsias de linfonodos) imediatamente."}, "difficulty": "dificil", "subspecialty": "Infectologia", "subject": "Tuberculose", "tags": ["LF-LAM", "TB-HIV", "Diagnóstico Rápido", "Tecnologia em Saúde"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 49);